  "$id": "https://example.com/catalogs/pricing/v1/catalog.json",



  "catalogId": "https://example.com/catalogs/pricing/v1/catalog.json",



  "protocolVersion": "1.0",



  "functions": {



    "shareProduct": {



      "type": "object",



      "description": "Opens the device share sheet for a produc

