// Absolute path to a repo-relative location, from docs/.vitepress/.
const at = (relative: string): string =>
  fileURLToPath(new URL(`../../${relative}`, import.meta.url));

// During `vitepress dev`, rebuild the workspace packages the docs consume whenever their source
// changes, so edits to the libraries show up live instead of only at the next full build.
//
// Builds invoke each package's `node` script DIRECTLY, not `vp run …`. `vpr docs:dev` runs vitepress
// under `vp`, and vite-plus cannot spawn a nested `vp` from inside that process — it dies with
// "Failed to spawn process: os error 22". A direct `node` invocation is unaffected. The generated CSS
// the theme imports comes from each package's `generate` script; the CSS API pages come from docs'
// `build-css-api`. Two outputs reach the browser: the generated CSS (watched via `outputWatchPaths` →
// HMR) and the CSS API `.md` (rebuilt by the `docs:api:css` node — VitePress watches the emitted files
// itself). A components edit regenerates the sheet, then cascades (`dependents`) into a CSS-API rebuild.
//
// NOTE: `@pantoken/web-components` is imported from SOURCE by the docs theme (theme/index.ts), not its
// `dist` — so Vite hot-reloads element `.ts` + co-located `.css` edits directly, with no `vp pack` and
// no orchestrator node. Its source graph is Node-free and codegen-free (CSS via Vite `?inline`), so
// there's nothing to build here. The plugin decoration sheets, the docs demo snippets, and the token
// sheet each get a node below so their previews/`@example` pages stay live too.
const orchestrator = workspaceOrchestrator({
  upstream: [
    {
      name: "@pantoken/css",
      dir: at("formats/css"),
      watchPaths: [at("formats/css/src")],
      build: ["node", "scripts/generate.ts"],
      // A `toCss` emitter change should re-theme the site sheet too (site-themes.ts imports it).
      dependents: ["@pantoken/docs#site-themes"],
    },
    {
      // Rewrite the whole-site token sheet (theme/generated/site-themes.css + the demos-assets copy) from
      // SOURCE (site-themes.ts imports @pantoken/css + @pantoken/tokens from src). Watches the resolved
      // token IR (`formats/tokens/generated/*.json`, what the tokens barrel reads) and the tokens src so
      // a token-value edit re-themes every preview live; also cascaded by @pantoken/css for emitter edits.
      // The theme imports the sheet (module-graph HMR); the demos-assets copy drives the /play iframes.
      name: "@pantoken/docs#site-themes",
      dir: at("docs"),
      watchPaths: [at("formats/tokens/generated"), at("formats/tokens/src")],
      build: ["node", "scripts/site-themes.ts"],
      dependents: [],
    },
    {
      // A component edit (`formats/components/src/**`) must recompile the per-theme string module
      // (`src/generated/component-styles.ts`) FIRST — `generate.ts` only consumes it. This node runs
      // that recompile, then cascades to the `generate` + docs-sheet nodes below. The orchestrator
      // can't run the package's `generate` npm task (it'd `vp run …`, which can't spawn nested here),
      // so the two steps are wired as separate direct-`node` nodes.
      name: "@pantoken/components#styles",
      dir: at("formats/components"),
      watchPaths: [at("formats/components/src")],
      // Loop guard: component-styles.ts rewrites src/generated/component-styles.ts (unconditionally),
      // and generate.ts rewrites src/generated/_records.css — both under the watched src dir. Without
      // this the recompile would retrigger itself forever.
      ignore: ["generated/**"],
      build: ["node", "scripts/component-styles.ts"],
      dependents: ["@pantoken/components"],
    },
    {
      // Regenerate the shipped `generated/*.css` (the CSS-API `.md` pages parse `generated/components.css`).
      // Dependent-only: the scheduler resolves it by name from `#styles` above. `outputWatchPaths`
      // (`formats/components/generated`) bridges the result into HMR.
      name: "@pantoken/components",
      dir: at("formats/components"),
      watchPaths: [],
      build: ["node", "scripts/generate.ts"],
      dependents: [
        "@pantoken/docs#components-sheet",
        "@pantoken/docs#component-assets",
        "@pantoken/docs#docs:api:css",
      ],
    },
    {
      // Pendo's source CSS is embedded before the demo asset imports `buildPendoCss`; keeping these
      // as separate nodes avoids nested `vp` calls and refreshes the runner iframe on source edits.
      name: "@pantoken/pendo#docs",
      dir: at("renderers/pendo"),
      watchPaths: [at("renderers/pendo/src")],
      build: ["node", "scripts/embed.ts"],
      dependents: ["@pantoken/docs#pendo-asset"],
    },
    {
      name: "@pantoken/docs#pendo-asset",
      dir: at("docs"),
      watchPaths: [],
      build: ["node", "scripts/stage-pendo-asset.ts"],
      dependents: [],
    },
    {
      // Rewrite the docs-only multi-theme component sheet the previews/demos actually load
      // (theme/generated/components.css + public/demos-assets/components.css). It reads the components
      // SOURCE barrel (see scope-components.ts), so it reflects the recompiled module. The theme copy is
      // in Vite's module graph, so Vite hot-updates it on rewrite. Dependent-only.
      name: "@pantoken/docs#components-sheet",
      dir: at("docs"),
      watchPaths: [],
      build: ["node", "scripts/components-sheet.ts"],
      dependents: [],
    },
    {
      // Re-stage the single-theme component sheets (base/prose/icons/select/utilities) the `/play` runner
      // loads into public/demos-assets/, copied from the freshly-regenerated `formats/components/generated`.
      // The main-doc theme imports those generated sheets directly (HMR via outputWatchPaths); the `/play`
      // iframes load them by URL from public/, so writing here triggers a Vite full reload. Dependent-only.
      name: "@pantoken/docs#component-assets",
      dir: at("docs"),
      watchPaths: [],
      build: ["node", "scripts/stage-component-assets.ts"],
      dependents: [],
    },
    // The decoration plugins each regenerate their `generated/<name>.css` from source with a plain
    // `node scripts/generate.ts` (no `vp pack`; the sheet is a sibling of `src`, so no watch loop). The
    // three with a demo sheet re-stage it into demos-assets AND rebuild their CSS-API `@example` pages;
    // logos/primitives have `@example` pages but no demo sheet, so they only cascade to the CSS-API build.
    // `transition`/`stacking` are tokens-only plugins now (no generated CSS) — their CSS lives in, and
    // rebuilds via, `@pantoken/components` above.
    {
      name: "@pantoken/plugin-visual-debug",
      dir: at("plugins/pantoken/visual-debug"),
      watchPaths: [at("plugins/pantoken/visual-debug/src")],
      build: ["node", "scripts/generate.ts"],
      dependents: ["@pantoken/docs#plugin-assets", "@pantoken/docs#docs:api:css"],
    },
    {
      name: "@pantoken/plugin-logos",
      dir: at("plugins/pantoken/logos"),
      watchPaths: [at("plugins/pantoken/logos/src")],
      build: ["node", "scripts/generate.ts"],
      dependents: ["@pantoken/docs#docs:api:css"],
    },
    {
      name: "@pantoken/plugin-primitives",
      dir: at("plugins/pantoken/primitives"),
      watchPaths: [at("plugins/pantoken/primitives/src")],
      build: ["node", "scripts/generate.ts"],
      dependents: ["@pantoken/docs#docs:api:css"],
    },
    {
      name: "@pantoken/plugin-custom-components#styles",
      dir: at("plugins/pantoken/custom-components"),
      watchPaths: [at("plugins/pantoken/custom-components/src")],
      ignore: ["generated/**"],
      build: ["node", "scripts/component-styles.ts"],
      dependents: ["@pantoken/plugin-custom-components"],
    },
    {
      name: "@pantoken/plugin-custom-components",
      dir: at("plugins/pantoken/custom-components"),
      watchPaths: [],
      build: ["node", "scripts/generate.ts"],
      dependents: ["@pantoken/docs#docs:api:css", "@pantoken/docs#plugin-assets"],
    },
    {
      name: "@pantoken/plugin-layouts",
      dir: at("plugins/pantoken/layouts"),
      watchPaths: [at("plugins/pantoken/layouts/src")],
      build: ["node", "scripts/generate.ts"],
      dependents: ["@pantoken/docs#docs:api:css"],
    },
    {
      // Re-stage the visual-debug decoration sheet into public/demos-assets/ from the plugin's
      // freshly-generated sheet. Dependent-only; writing into public/ triggers a Vite full reload so the
      // <head>-linked chrome and the /play iframes refetch. See stage-plugin-assets.ts.
      name: "@pantoken/docs#plugin-assets",
      dir: at("docs"),
      watchPaths: [],
      build: ["node", "scripts/stage-plugin-assets.ts"],
      dependents: [],
    },
    {
      // Re-render the committed demo templates (docs/demos/<component>/index.html) into public/demos/ on
      // edit. Full reload
      // (public/ write) refreshes an open /play demo. See stage-demo-snippets.ts.
      name: "@pantoken/docs#demo-snippets",
      dir: at("docs"),
      watchPaths: [at("docs/demos")],
      build: ["node", "scripts/stage-demo-snippets.ts"],
      dependents: [],
    },
    {

      // Re-render the canvas-theme-editor scaffold template and build it into the static bundle the
      // "Canvas RCE" utility page embeds via iframe (public/tools/canvas-rce/). Dependent-only —
      // triggered by `@pantoken/scaffold#generate` above so it always rebuilds from freshly
      // regenerated templates, never a stale copy.
      name: "@pantoken/docs#canvas-rce",
      dir: at("docs"),
      watchPaths: [],
      build: ["node", "scripts/build-canvas-rce.ts"],
      dependents: [],
    },
  ],
  outputWatchPaths: [
    // Generated CSS imported via `@fs` and the Canvas RCE static iframe bundle — bridged into Vite's
    // watcher. (Web components are imported from source now, so their `dist` no longer needs bridging.)
    at("formats/css/generated"),
    at("formats/components/generated"),
    at("plugins/pantoken/custom-components/generated"),
    at("docs/public/tools/canvas-rce"),
  ],
});

const localeEntries = Object.entries(LOCALE_THEMES) as [
  DocsLocale,
  (typeof LOCALE_THEMES)[DocsLocale],
][];

const rootLocaleOnly = process.env.DOCS_ROOT_LOCALE_ONLY === "1";

// One locale per build. VitePress bakes a single `__ASSETS_DIR__` into the client router, so the only
// way to keep any one directory under static-host per-directory file caps is to build each locale
// separately into `assets/<locale>/` and merge the outputs. Unset means "every locale in one build".
const buildLocale = process.env.DOCS_LOCALE;
const isLocaleScoped = buildLocale !== undefined;

// A per-locale build (see build-locales.ts) only ever renders `buildLocale`'s own pages, so every
// OTHER locale's full nav/sidebar would be dead weight in this build's site-data script (see the
// `localesConfig` comment below for why it's safe to drop). Unscoped `vitepress dev` builds every
// locale in one process, so every locale stays "active" there.
const isActiveLocale = (localeKey: DocsLocale): boolean =>
  !isLocaleScoped || localeKey === buildLocale;

const docsRoot = at("docs");

const walkMarkdown = (dir: string, prefix = ""): string[] => {
  const files: string[] = [];
  for (const name of readdirSync(dir)) {
    if (name === ".vitepress") continue;
    const fullPath = `${dir}/${name}`;
    const relativePath = prefix ? `${prefix}/${name}` : name;
    const stat = statSync(fullPath);
    if (stat.isDirectory()) files.push(...walkMarkdown(fullPath, relativePath));
    else if (relativePath.endsWith(".md")) files.push(relativePath);
  }
  return files;
};

const partialPages = readPartialPages();
const partialPageExcludes = partialPages
  ? walkMarkdown(docsRoot).filter((page) => !partialPages.has(page))
  : [];

// The root locale owns every page outside a locale directory, so it excludes the locale trees; a
// non-root locale excludes the other locales plus everything at the docs root. Both stay as globs —
// listing the ~40k excluded pages individually makes VitePress's per-file matching quadratic.
const localePageExcludes = !isLocaleScoped
  ? []
  : buildLocale === "root"
    ? NON_ROOT_LOCALES.map((locale) => `${locale}/**`)
    : [
        ...NON_ROOT_LOCALES.filter((locale) => locale !== buildLocale).map(
          (locale) => `${locale}/**`,
        ),
        ...readdirSync(docsRoot)
          .filter((name) => name !== ".vitepress" && !NON_ROOT_LOCALES.includes(name as DocsLocale))
          .map((name) => (statSync(`${docsRoot}/${name}`).isDirectory() ? `${name}/**` : name))
          .filter((entry) => entry.endsWith("/**") || entry.endsWith(".md")),
      ];

const loadSidebar = (relativePath: string): DefaultTheme.SidebarItem[] => {
  const sidebarPath = fileURLToPath(new URL(relativePath, import.meta.url));
  return existsSync(sidebarPath)
    ? (JSON.parse(readFileSync(sidebarPath, "utf8")) as DefaultTheme.SidebarItem[])
    : [];
};

// Only load the (potentially large) TypeDoc sidebar JSON for locales that actually get a full
// themeConfig below — a per-locale build never needs the other 43 locales' copies.
const typedocSidebarByLocale = Object.fromEntries(
  localeEntries
    .filter(([localeKey]) => isActiveLocale(localeKey))
    .map(([localeKey, locale]) => [localeKey, loadSidebar(locale.typedocSidebarPath)]),
) as Record<DocsLocale, DefaultTheme.SidebarItem[]>;

// `DOCS_ROOT_LOCALE_ONLY=1` builds skip every `<locale>/api/**` page (see `srcExclude` below), so a
// non-root locale's own API routes would 404. Serve the English API tree from those locales instead:
// the reference exists, just untranslated.
const apiPrefixFor = (localeKey: DocsLocale): string =>
  rootLocaleOnly ? LOCALE_THEMES.root.apiPrefix : LOCALE_THEMES[localeKey].apiPrefix;

// TypeDoc emits one monorepo-wide tree; partition it by package/CSS route so a page only ever needs
// its own section instead of every package's nav. Computed once per active locale, then merged into
// that locale's `themeConfig.sidebar` below as additional path-prefix keys — VitePress's own
// multi-sidebar resolution (`getSidebar`) picks the one matching key per page, so a guide page still
// carries none of it and an API page still carries only its own route.
const apiSidebarRoutesByLocale = Object.fromEntries(
  localeEntries
    .filter(([localeKey]) => isActiveLocale(localeKey))
    .map(([localeKey, locale]) => [
      localeKey,
      partitionApiSidebar(
        typedocSidebarByLocale[localeKey],
        locale.sidebar.api,
        apiPrefixFor(localeKey),
        locale.sidebar.css,
        locale.sidebar.apiGroups,
        locale.sidebar.apiOverview,
        locale.sidebar.guides,
        `${locale.guidePrefix}getting-started`,
      ),
    ]),
) as Partial<Record<DocsLocale, ReturnType<typeof partitionApiSidebar>>>;

// A script-specific wordmark, when one exists (see `NON_LATIN_LOCALES` in i18n.ts); every other
// locale falls back to the default Latin logo set below.
const localesConfig = Object.fromEntries(
  localeEntries.map(([localeKey, locale]) => {
    // A per-locale build (see build-locales.ts) already builds every OTHER locale as its own
    // independent site with its own full nav/sidebar. The language switcher (VPNavBarExtra.vue)
    // does a hard `window.location.assign`, not an SPA route change, so this build never needs to
    // render another locale's pages — only enough to list it in the language dropdown (`useLangs()`
    // reads `label`/`lang`; `link` defaults from the key).
    if (!isActiveLocale(localeKey)) {
      return [localeKey, { label: locale.label, lang: locale.lang, dir: locale.dir }];
    }
    const guideSidebar = [
      {
        text: locale.sidebar.guides,
        items: [
          {
            text: locale.sidebar.gettingStarted,
            link: `${locale.guidePrefix}getting-started`,
          },
          {
            text: locale.sidebar.architecture,
            link: `${locale.guidePrefix}architecture`,
          },
          { text: locale.sidebar.cli, link: `${locale.guidePrefix}cli` },
          { text: locale.sidebar.plugins, link: `${locale.guidePrefix}plugins` },
          {
            text: locale.sidebar.utilities,
            collapsed: true,
            items: [
              {
                text: locale.sidebar.cdnPicker,
                link: `${locale.guidePrefix}cdn-picker`,
              },
              {
                text: locale.sidebar.registry,
                link: `${localeKey === "root" ? "/" : `/${localeKey}/`}r/`,
              },
              {
                text: locale.sidebar.agentTools,
                link: `${locale.guidePrefix}agent-tools`,
              },
              {
                text: locale.sidebar.canvasRce,
                link: `${locale.guidePrefix}canvas-rce`,
              },
            ],
          },
        ],
      },
      { items: [{ text: locale.sidebar.api, link: apiPrefixFor(localeKey) }] },
      { items: [{ text: locale.sidebar.css, link: `${apiPrefixFor(localeKey)}css/` }] },
    ];

    return [
      localeKey,
      {
        label: locale.label,
        lang: locale.lang,
        dir: locale.dir,
        title: "pantoken",
        description: locale.description,
        themeConfig: {
          nav: [
            { text: locale.nav.guide, link: `${locale.guidePrefix}getting-started` },
            { text: locale.nav.css, link: `${apiPrefixFor(localeKey)}css/` },
            { text: locale.nav.api, link: apiPrefixFor(localeKey) },
          ],
          sidebar: {
            [locale.guidePrefix]: guideSidebar,
            [`${localeKey === "root" ? "/" : `/${localeKey}/`}r/`]: guideSidebar,
            // Per-route API/CSS sidebars (see `apiSidebarRoutesByLocale` above) — VitePress's
            // `getSidebar` matches the longest key that's a prefix of the current page's path, so
            // each API page only ever renders its own route's (already-partitioned) subtree.

/** The English source of truth for every translatable UI string in {@link UiStrings}. */
const sourceUiStrings = Object.fromEntries(
  Object.entries(chromeSource)
    .filter(([key]) => key !== "$schema")
    .map(([key, entry]) => [key, (entry as { message: string }).message]),
);

function unflattenStrings(flat: Record<string, string>): UiStrings {
  const result: Record<string, unknown> = {};
  for (const [path, value] of Object.entries(flat)) {
    const parts = path.split(".");
    let target = result;
    for (const part of parts.slice(0, -1)) {
      target[part] ??= {};
      target = target[part] as Record<string, unknown>;
    }
    target[parts.at(-1)!] = value;
  }
  return result as unknown as UiStrings;
}

/** English UI strings used as the fallback for localized documentation chrome. */
export const ENGLISH_UI_STRINGS: UiStrings = unflattenStrings(sourceUiStrings);

/** Structural, non-translated per-locale metadata: route prefixes, BCP47 tag, direction, sidebar path. */
export interface LocaleStructure {
  label: string;
  lang: string;
  dir: "ltr" | "rtl";
  guidePrefix: string;
  apiPrefix: string;
  // The CSS reference is merged into the TypeDoc sidebar by `@cssdoc/typedoc`, so there's one path.
  typedocSidebarPath: string;
}

const structureFor = (locale: DocsLocale): LocaleStructure => {
  if (locale === "root") {
    return {
      label: "English",
      lang: "en-US",
      dir: "ltr",
      guidePrefix: "/guide/",
      apiPrefix: "/api/",
      typedocSidebarPath: "../api/typedoc-sidebar.json",
    };
  }
  const meta = LOCALES[locale];
  return {
    label: meta.label,
    lang: locale,
    dir: meta.dir,
    guidePrefix: `/${locale}/guide/`,
    apiPrefix: `/${locale}/api/`,
    typedocSidebarPath: `../${locale}/api/typedoc-sidebar.json`,
  };
};

/** Recursively collect every leaf string in an object tree, keyed by its dotted path. */
export function flattenStrings(value: unknown, prefix = ""): { path: string; text: string }[] {
  if (typeof value === "string") return [{ path: prefix, text: value }];
  if (value && typeof value === "object") {
    return Object.entries(value as Record<string, unknown>).flatMap(([key, child]) =>
      flattenStrings(child, prefix ? `${prefix}.${key}` : key),
    );
  }
  return [];
}

/** Deep-clone `base`, overwriting each leaf whose dotted path is in `overrides`. */
function applyOverrides<T>(base: T, overrides: ReadonlyMap<string, string>, prefix = ""): T {
  if (typeof base === "string") {
    return (overrides.get(prefix) ?? base) as T;
  }
  if (base && typeof base === "object") {
    const out: Record<string, unknown> = { ...(base as Record<string, unknown>) };
    for (const [key, child] of Object.entries(base as Record<string, unknown>)) {
      out[key] = applyOverrides(child, overrides, prefix ? `${prefix}.${key}` : key);
    }
    return out as T;
  }
  return base;
}

// Every UI leaf, computed once — reused by the docs chrome renderer and drift checker.
const ENGLISH_UI_LEAVES = flattenStrings(ENGLISH_UI_STRINGS);

/**
 * Resolve the locale's `docs.chrome` PO catalog over the English defaults, so untranslated strings
 * fall back to English rather than disappearing.
 */
const uiStringsFor = (locale: DocsLocale): UiStrings => {
  if (locale === "root") return ENGLISH_UI_STRINGS;
  const config = loadConfig(new URL("../../i18n.config.json", import.meta.url).pathname);
  const resolved = resolveMessagesForLocale(
    config,
    new URL("../../", import.meta.url).pathname,
    "docs.chrome",
    locale,
  );
  const overrides = new Map(ENGLISH_UI_LEAVES.map(({ path }) => [path, resolved.strings[path]]));
  return applyOverrides(ENGLISH_UI_STRINGS, overrides);
};

/** Per-locale route structure plus all translated UI chrome strings. */
export type LocaleTheme = LocaleStructure & UiStrings;

// Computed lazily (and memoized) behind a Proxy: merely importing this module — e.g. for
// `NON_ROOT_LOCALES`/`ENGLISH_UI_STRINGS`/`flattenStrings` stay cheap to import; PO resolution only
// runs once something actually reads a `LOCALE_THEMES` property (the real docs build).
let computedLocales: Record<DocsLocale, LocaleTheme> | undefined;
const computeLocales = (): Record<DocsLocale, LocaleTheme> => {
  computedLocales ??= Object.fromEntries(
    ALL_DOCS_LOCALES.map((locale) => [
      locale,
      { ...structureFor(locale), ...uiStringsFor(locale) },
    ]),
  ) as Record<DocsLocale, LocaleTheme>;
  return computedLocales;
};

/** Per-locale metadata — route prefixes, nav/sidebar labels, and all translated UI chrome. */
export const LOCALE_THEMES: Record<DocsLocale, LocaleTheme> = new Proxy(
  {} as Record<DocsLocale, LocaleTheme>,
  {
    get: (_target, prop) => computeLocales()[prop as DocsLocale],
    has: (_target, prop) => prop in computeLocales(),
    ownKeys: () => Reflect.ownKeys(computeLocales()),
    getOwnPropertyDescriptor: (_target, prop) =>
      Object.getOwnPropertyDescriptor(computeLocales(), prop),
  },
);

/**
 * Generate static shadcn/ui registry files under `docs/public/r/` conforming to
 * the registry JSON schema specification (https://ui.shadcn.com/schema/registry.json and
 * https://ui.shadcn.com/schema/registry-item.json).
 *
 * Emits:
 * - `docs/public/r/registry.json` (the full catalog)
 * - `docs/public/r/[name].json` (individual item manifests for all themes, components, and hooks)
 * - `docs/.vitepress/theme/generated/registry.json` (the catalog imported by the docs app)
 */
import { mkdirSync, readdirSync, unlinkSync, writeFileSync } from "node:fs";
import { resolve } from "node:path";
import { COMPONENTS } from "../../formats/components/src/components/index.ts";
import type {
  RegistryCatalog,
  RegistryItem,
} from "../.vitepress/theme/components/registry-types.ts";
import { buildPluginRegistryItems } from "./registry-plugins.ts";

const defaultOutDir = resolve(import.meta.dirname, "../public/r");
const defaultSourceDir = resolve(import.meta.dirname, "../.vitepress/theme/generated");
const AUTHOR = "pantoken <https://pantoken.app>";

function cssImports(paths: readonly string[]): Record<string, Record<string, string>> {
  return Object.fromEntries(paths.map((path) => [`@import "${path}"`, {}]));
}

/** Build the complete shadcn/ui registry catalog object in-memory. */
export function buildRegistryCatalog(): RegistryCatalog {
  const items: RegistryItem[] = [];

  // 1. Base / Theme items
  items.push({
    name: "theme-canvas",
    type: "registry:theme",
    title: "Canvas LMS Theme",
    description: "Instructure Canvas LMS theme variables bridging to shadcn/ui custom properties.",
    author: AUTHOR,
    dependencies: ["@pantoken/css", "@pantoken/shadcn"],
    registryDependencies: ["@pantoken/base"],
    css: cssImports(["@pantoken/css/style.canvas.css"]),
  });

  items.push({
    name: "theme-canvas-high-contrast",
    type: "registry:theme",
    title: "Canvas High Contrast Theme",
    description: "Canvas LMS High Contrast theme variables for WCAG AAA compliance.",
    author: AUTHOR,
    dependencies: ["@pantoken/css", "@pantoken/shadcn"],
    registryDependencies: ["@pantoken/base"],
    css: cssImports(["@pantoken/css/style.canvas-high-contrast.css"]),
  });

  items.push({
    name: "theme-rebrand",
    type: "registry:theme",
    title: "Instructure Next gen Theme",
    description: "Modern Instructure brand theme variables.",
    author: AUTHOR,
    dependencies: ["@pantoken/css", "@pantoken/shadcn"],
    registryDependencies: ["@pantoken/base"],
    css: cssImports(["@pantoken/css/style.css"]),
  });

  items.push({
    name: "base",
    type: "registry:base",
    title: "Pantoken Base System",
    description:
      "Pantoken core design token system, CSS custom properties, and semantic components.",
    author: AUTHOR,
    dependencies: ["@pantoken/css", "@pantoken/components", "@pantoken/shadcn"],
    css: cssImports([
      "@pantoken/css/style.css",
      "@pantoken/components/base.css",
      "@pantoken/shadcn/theme.css",
      "@pantoken/shadcn/tailwind-v4.css",
    ]),
  });

  // 2. CSS component items. Member records are installed with their owning root component.
  for (const comp of COMPONENTS.filter(({ name }) => !name.includes("."))) {
    const name = comp.name;
    const title = name.charAt(0).toUpperCase() + name.slice(1);
    const description = `Instructure ${title} component styled with semantic .instui-${name} classes.`;
    const members = COMPONENTS.filter(({ name: candidate }) =>
      candidate.startsWith(`${name}.`),
    ).map(({ name: member }) => member);

    items.push({
      name,
      type: "registry:style",
      title,
      description,
      author: AUTHOR,
      dependencies: ["@pantoken/components"],
      registryDependencies: ["@pantoken/base"],
      css: cssImports([
        `@pantoken/components/${name}.css`,
        ...members.map((member) => `@pantoken/components/${member}.css`),
      ]),
      docs: `Apply \`class="instui-${name}"\` to semantic HTML. See https://pantoken.app/api/css/components/${name}.`,
      categories: ["components"],
      meta: {
        className: `instui-${name}`,
        members,
        framework: "css",
      },
    });
  }

  items.push(...buildPluginRegistryItems());

  return {
    $schema: "https://ui.shadcn.com/schema/registry.json",
    name: "pantoken",
    homepage: "https://pantoken.app",
    items,
  };
}

/** Write registry catalog and individual item JSON manifests to disk. */
export function writeRegistry(options?: { outDir?: string; sourceDir?: string }): {
  catalogPath: string;
  count: number;
} {
  const outDir = options?.outDir ?? defaultOutDir;
  const sourceDir = options?.sourceDir ?? defaultSourceDir;
  mkdirSync(outDir, { recursive: true });
  mkdirSync(sourceDir, { recursive: true });

  const catalog = buildRegistryCatalog();
  const catalogPath = resolve(outDir, "registry.json");
  const sourceCatalogPath = resolve(sourceDir, "registry.json");
  // The public directory index must omit file contents. Keep them in the
  // browser's source catalog and individual manifests for previews and installs.
  const publicCatalog = {
    ...catalog,
    items: catalog.items.map((item) => ({
      ...item,
      ...(item.files && {
        files: item.files.map(({ content: _content, ...file }) => file),
      }),
    })),
  };
  writeFileSync(catalogPath, JSON.stringify(publicCatalog, null, 2) + "\n");
  writeFileSync(sourceCatalogPath, JSON.stringify(catalog, null, 2) + "\n");

  // Write individual item files
  for (const item of catalog.items) {
    const itemPayload = {
      $schema: "https://ui.shadcn.com/schema/registry-item.json",
      ...item,
    };
    const itemPath = resolve(outDir, `${item.name}.json`);
    writeFileSync(itemPath, JSON.stringify(itemPayload, null, 2) + "\n");
  }

  const expectedFiles = new Set([
    "registry.json",
    ...catalog.items.map(({ name }) => `${name}.json`),
  ]);
  for (const file of readdirSync(outDir)) {
    if (file.endsWith(".json") && !expectedFiles.has(file)) unlinkSync(resolve(outDir, file));
  }

  return { catalogPath, count: catalog.items.length };
}

if (import.meta.url === `file://${process.argv[1]}`) {
  const { catalogPath, count } = writeRegistry();
  console.log(`✓ registry: wrote ${catalogPath} (${count} items)`);
  console.log(`✓ registry: wrote ${count} item files to ${defaultOutDir}`);
}

// @vitest-environment happy-dom
import { afterEach, expect, test } from "vite-plus/test";
import { applySpacing } from "@pantoken/interactions";
import { iconSvg, register } from "../src/index.ts";

register();
afterEach(() => {
  document.body.innerHTML = "";
});

// ── applySpacing (the shared spacing mixin's worker) ─────────────────────────────

test("applySpacing resolves the margin/padding shorthands from keywords and raw lengths", () => {
  const el = document.createElement("div");
  el.setAttribute("margin", "small none");
  el.setAttribute("padding", "2rem");
  applySpacing(el);
  // happy-dom serializes a bare `0` length as `0px`.
  expect(el.style.margin).toBe("var(--instui-spacing-space-sm) 0px");
  expect(el.style.padding).toBe("2rem");
});

test("applySpacing resolves per-side physical and logical attributes", () => {
  const el = document.createElement("div");
  el.setAttribute("margin-top", "medium");
  el.setAttribute("padding-inline-start", "small");
  applySpacing(el);
  expect(el.style.getPropertyValue("margin-top")).toBe("var(--instui-spacing-space-md)");
  expect(el.style.getPropertyValue("padding-inline-start")).toBe("var(--instui-spacing-space-sm)");
});

test("applySpacing clears a managed property when its attribute is removed", () => {
  const el = document.createElement("div");
  el.setAttribute("margin", "small");
  applySpacing(el);
  expect(el.style.margin).not.toBe("");
  el.removeAttribute("margin");
  applySpacing(el);
  expect(el.style.margin).toBe("");
});

test("applySpacing ignores an unmanaged margin-<side> like margin-foo", () => {
  const el = document.createElement("div");
  el.setAttribute("margin-foo", "small");
  applySpacing(el);
  expect(el.style.getPropertyValue("margin-foo")).toBe("");
});

// ── withSpacing integration: spacing works on every element with no per-element code ──

test("an element applies its margin attribute to the host style on connect", () => {
  document.body.innerHTML = `<instui-button margin="small" margin-top="medium">Go</instui-button>`;
  const el = document.querySelector("instui-button") as HTMLElement;
  expect(el.style.margin).toBe("var(--instui-spacing-space-sm)");
  expect(el.style.getPropertyValue("margin-top")).toBe("var(--instui-spacing-space-md)");
});

// ── syncInvoker: the host's invoker attributes mirror onto the inner <button> IDL ───

test("popovertarget mirrors onto the inner button and defaults the action to toggle", () => {
  document.body.innerHTML = `<instui-button popovertarget="pop">Open</instui-button><div id="pop">x</div>`;
  const el = document.querySelector("instui-button") as HTMLElement;
  const target = document.getElementById("pop");
  el.dispatchEvent(new Event("pointerdown"));
  const btn = el.shadowRoot?.querySelector("button") as HTMLButtonElement & {
    popoverTargetElement?: Element | null;
    popoverTargetAction?: string;
  };
  expect(btn.popoverTargetElement).toBe(target);
  expect(btn.popoverTargetAction).toBe("toggle");
});

test("popovertargetaction overrides the default action", () => {
  document.body.innerHTML = `<instui-button popovertarget="pop" popovertargetaction="show">Open</instui-button><div id="pop">x</div>`;
  const el = document.querySelector("instui-button") as HTMLElement;
  el.dispatchEvent(new Event("keydown"));
  const btn = el.shadowRoot?.querySelector("button") as HTMLButtonElement & {
    popoverTargetAction?: string;
  };
  expect(btn.popoverTargetAction).toBe("show");
});

test("command/commandfor mirror onto the inner button's command IDL", () => {
  document.body.innerHTML = `<instui-button command="--show" commandfor="dlg">Show</instui-button><div id="dlg">x</div>`;
  const el = document.querySelector("instui-button") as HTMLElement;
  const target = document.getElementById("dlg");
  el.dispatchEvent(new Event("pointerdown"));
  const btn = el.shadowRoot?.querySelector("button") as HTMLButtonElement & {
    commandForElement?: Element | null;
    command?: string;
  };
  expect(btn.commandForElement).toBe(target);
  expect(btn.command).toBe("--show");
});

// ── register options against a real registry ────────────────────────────────────

test("register mints working elements under a custom prefix", () => {
  register(customElements, { prefix: "xwc" });
  document.body.innerHTML = `<xwc-button variant="primary">Go</xwc-button>`;
  const el = document.querySelector("xwc-button") as HTMLElement;
  expect(el.shadowRoot?.querySelector("button")?.className).toContain("-color-primary");
});

test("register `only` limits the registered subset (others stay undefined)", () => {
  register(customElements, { prefix: "sub", only: ["button", "alert"] });
  expect(customElements.get("sub-button")).toBeTruthy();
  expect(customElements.get("sub-alert")).toBeTruthy();
  expect(customElements.get("sub-badge")).toBeFalsy();
});

test("register `only` pulls in nested render dependencies transitively", () => {
  register(customElements, { prefix: "dep", only: ["date-time-input"] });
  expect(customElements.get("dep-date-time-input")).toBeTruthy();
  expect(customElements.get("dep-date-input")).toBeTruthy();
  expect(customElements.get("dep-calendar")).toBeTruthy();
  expect(customElements.get("dep-badge")).toBeFalsy();
});

test("register is a safe no-op without a registry", () => {
  expect(() => register(undefined)).not.toThrow();
});

// ── locale / strings / dir options ──────────────────────────────────────────────

test("strings option overrides the drilldown back-row label", () => {
  register(customElements, { prefix: "l10n", strings: { back: "Vissza" } });
  const tpl = document.createElement("template");
  tpl.innerHTML = `<l10n-drilldown active="root"><div data-page="root"><div class="item" data-goto="sub">X</div></div><div data-page="sub"><div class="item">Y</div></div></l10n-drilldown>`;
  document.body.appendChild(tpl.content);
  const el = document.querySelector("l10n-drilldown") as HTMLElement;
  el.shadowRoot?.querySelector<HTMLElement>("[data-goto='sub']")?.click();
  expect(el.shadowRoot?.querySelector(".-drilldown-back")?.textContent).toBe("Vissza");
});

test("strings option overrides calendar nav aria-labels", () => {
  register(customElements, {
    prefix: "l10nav",
    strings: { prevMonth: "Előző hónap", nextMonth: "Következő hónap" },
  });
  document.body.innerHTML = `<l10nav-calendar value="2026-07-08"></l10nav-calendar>`;
  const el = document.querySelector("l10nav-calendar") as HTMLElement;
  expect(
    el.shadowRoot?.querySelector('[command="--calendar-prev"]')?.getAttribute("aria-label"),
  ).toBe("Előző hónap");
  expect(
    el.shadowRoot?.querySelector('[command="--calendar-next"]')?.getAttribute("aria-label"),
  ).toBe("Következő hónap");
});

test("dir:rtl swaps the calendar chevron icons", () => {
  register(customElements, { prefix: "rtl", dir: "rtl" });
  document.body.innerHTML = `<rtl-calendar value="2026-07-08"></rtl-calendar>`;
  const el = document.querySelector("rtl-calendar") as HTMLElement;
  const prev = el.shadowRoot?.querySelector('[command="--calendar-prev"]');
  const next = el.shadowRoot?.querySelector('[command="--calendar-next"]');
  // Compare path data — DOM re-serializes self-closing SVG tags, raw string comparison fails.
  const paths = (svg: string) =>
    svg
      .match(/d="[^"]+"/g)
      ?.sort()
      .join(",") ?? "";
  // RTL: prev button sits on the right — uses chevron-right glyph (swapped from LTR).
  expect(paths(prev?.innerHTML ?? "")).toBe(paths(iconSvg("chevron-right")));
  expect(paths(next?.innerHTML ?? "")).toBe(paths(iconSvg("chevron-left")));
});

test("dir:rtl swaps the drilldown back-row arrow icon", () => {
  register(customElements, { prefix: "rtldd", dir: "rtl" });
  const tpl = document.createElement("template");
  tpl.innerHTML = `<rtldd-drilldown active="root"><div data-page="root"><div class="item" data-goto="s">X</div></div><div data-page="s"><div class="item">Y</div></div></rtldd-drilldown>`;
  document.body.appendChild(tpl.content);
  const el = document.querySelector("rtldd-drilldown") as HTMLElement;
  el.shadowRoot?.querySelector<HTMLElement>("[data-goto='s']")?.click();
  // RTL: back row uses arrow-right glyph (not arrow-left as in LTR).
  const backRow = el.shadowRoot?.querySelector(".-drilldown-back");
  const paths = (svg: string) =>
    svg
      .match(/d="[^"]+"/g)
      ?.sort()
      .join(",") ?? "";
  expect(paths(backRow?.querySelector("svg")?.outerHTML ?? "")).toBe(paths(iconSvg("arrow-right")));
});

test("date-input always renders dir=ltr on the input regardless of page direction", () => {
  register(customElements, { prefix: "rtldi", dir: "rtl" });
  document.body.innerHTML = `<rtldi-date-input></rtldi-date-input>`;
  const el = document.querySelector("rtldi-date-input") as HTMLElement;
  expect(el.shadowRoot?.querySelector("input")?.getAttribute("dir")).toBe("ltr");
});

