/**
 * Every locale the docs site builds: `root` (English) plus every non-`en` locale from
 * `@pantoken/web-components`'s `LOCALES` (44 BCP47 tags — `en` is dropped since `root` already covers
 * US English). English regional variants (`en-AU`, `en-CA`, `en-GB`) get their own route prefix AND
 * their own translated UI strings — British/Australian/Canadian spelling and phrasing differ from US
 * English (colour/centre, -ise vs. -ize, etc.), so they go through the same translation pipeline as
 * every other locale rather than passing through the `root` English source untouched.
 * `LOCALES` is typed as `Record<string, LocaleInfo>` (its keys aren't a literal union), so
 * `DocsLocale` is a plain `string`.
 */
export type DocsLocale = string;

/** The non-`root` locale keys, in `LOCALES` order. */
export const NON_ROOT_LOCALES = Object.keys(LOCALES).filter((key) => key !== "en");

/**
 * Resolve a `DOCS_TRANSLATION_LOCALE` value — one entry or a comma/space-separated list — against
 * `fallback` (every locale when the variable is unset). Each entry is either a locale tag or a tier
 * name from `i18n.config.json`'s `locales.tiers` (`primary`, `secondary`, …), which expands to every
 * docs locale in that tier; the two can be mixed. Prefix an entry with `-` to subtract it, e.g.
 * `"-ga"` for every locale but Irish or `"primary,-hu"` for the primary tier without Hungarian; a
 * value of only subtractions starts from `fallback`. Throws on an entry that's neither a tag nor a
 * tier, so a typo fails loudly instead of quietly building an empty directory.
 */
export const parseRequestedLocales = (
  requested: string | undefined,
  fallback: readonly string[],
): readonly string[] => {
  const entries = (requested ?? "").split(/[,\s]+/).filter((entry) => entry.length > 0);
  if (entries.length === 0) return fallback;

  const tiers = loadConfig(new URL("../../i18n.config.json", import.meta.url).pathname).locales
    .tiers;
  const unknown: string[] = [];
  const expand = (entry: string): readonly string[] => {
    // resolveTier, not a raw pattern match: tiers are ordered, so `secondary`'s `"*"` must not
    // reclaim a locale that `primary` already matched.
    if (entry in tiers) return NON_ROOT_LOCALES.filter((l) => resolveTier(tiers, l) === entry);
    if (NON_ROOT_LOCALES.includes(entry)) return [entry];
    unknown.push(entry);
    return [];
  };

  const included: string[] = [];
  const excluded = new Set<string>();
  let hasInclude = false;
  for (const entry of entries) {
    if (entry.startsWith("-")) for (const locale of expand(entry.slice(1))) excluded.add(locale);
    else {
      hasInclude = true;
      included.push(...expand(entry));
    }
  }
  if (unknown.length > 0) {
    throw new Error(
      `Unknown DOCS_TRANSLATION_LOCALE value(s): ${unknown.join(", ")}. Supported tiers: ${Object.keys(tiers).join(", ")}. Supported locales: ${NON_ROOT_LOCALES.join(", ")}`,
    );
  }

  // Only subtractions (`"-ga"`) start from every locale; an include that expanded to nothing must not.
  const base = hasInclude ? included : fallback;
  const resolved = [...new Set(base)].filter((locale) => !excluded.has(locale));
  // A tier can be valid yet empty here — `source` is `["en"]`, which no docs locale belongs to.
  if (resolved.length === 0) {
    throw new Error(`DOCS_TRANSLATION_LOCALE=${requested ?? ""} matched no docs locale`);
  }
  return resolved;
};

/** Every docs locale, `root` first. */
const ALL_DOCS_LOCALES: readonly DocsLocale[] = ["root", ...NON_ROOT_LOCALES];

/**
 * Non-Latin scripts have a purpose-drawn wordmark in `@pantoken/plugin-logos`, keyed by the script
 * suffix here. `docs/scripts/stage-locale-logos.ts` copies those into
 * `docs/public/logo-{light,dark}-<script>.svg` for the nav, and `docs/scripts/gen-og.ts` sets the same
 * mark on the locale's social card. `zh-Hans`/`zh-Hant` share one Han-script mark; the Japanese file
 * is suffixed `jp`.
 */
export const NON_LATIN_LOCALES: Partial<Record<DocsLocale, string>> = {
  ar: "ar",
  el: "el",
  fa: "fa",
  he: "he",
  hi: "hi",
  hy: "hy",

/** Options for show/hide timing. */
export interface TooltipOptions {
  showDelay?: number;
  hideDelay?: number;
}

/** Handle returned by {@link initTooltip}. */
export interface TooltipHandle {
  /** Remove listeners/timers and restore the original managed marker and show class. */
  cleanup(): void;
  /** Dismiss until both pointer and focus leave, canceling pending timers. */
  cancelAndHide(): void;
}

/**
 * Own tooltip visibility after initialization, retaining CSS hover/focus as a no-JS fallback.
 * Pointer and focus are independent reasons to stay open; Escape dismisses until both leave.
 *
 *   CSS:  wrapper = .instui-tooltip element, tip = its .tip child
 *   WC:   wrapper = shadow .instui-tooltip, tip = shadow .tip
 */
export function initTooltip(
  wrapper: HTMLElement,
  tip: HTMLElement,
  options?: TooltipOptions,
): TooltipHandle {
  let timer: ReturnType<typeof setTimeout> | undefined;
  const originalManaged = wrapper.getAttribute("data-tooltip-managed");
  const originalShown = tip.classList.contains("-show");
  const document = wrapper.ownerDocument;
  const view = document.defaultView;
  if (!view) throw new Error("Tooltip positioning requires a document with a window.");
  const originalSide = tip.getAttribute("data-tooltip-side");
  const positionProperties = [
    "left",
    "top",
    "right",
    "bottom",
    "margin-top",
    "margin-right",
    "margin-bottom",
    "margin-left",
    "transform",
    "--pantoken-tooltip-viewport-inline-size",
    "--pantoken-tooltip-gap",
  ] as const;
  const originalPosition = positionProperties.map((property) => ({
    property,
    value: tip.style.getPropertyValue(property),
    priority: tip.style.getPropertyPriority(property),
  }));
  const restorePosition = () => {
    for (const { property, value, priority } of originalPosition) {
      if (value) tip.style.setProperty(property, value, priority);
      else tip.style.removeProperty(property);
    }
    if (originalSide === null) tip.removeAttribute("data-tooltip-side");
    else tip.setAttribute("data-tooltip-side", originalSide);
  };
  const position = () => {
    if (!tip.classList.contains("-show")) return;
    restorePosition();
    const style = view.getComputedStyle(tip);
    const gap = Math.max(
      ...[style.marginTop, style.marginRight, style.marginBottom, style.marginLeft].map(
        (value) => Number.parseFloat(value) || 0,
      ),
    );
    const visual = view.visualViewport;
    const left = (visual?.offsetLeft ?? 0) + gap;
    const top = (visual?.offsetTop ?? 0) + gap;
    const width = visual?.width ?? (document.documentElement.clientWidth || view.innerWidth);
    const height = visual?.height ?? (document.documentElement.clientHeight || view.innerHeight);
    const right = left + width - 2 * gap;
    const bottom = top + height - 2 * gap;
    tip.style.setProperty(
      "--pantoken-tooltip-viewport-inline-size",
      `${Math.max(0, width - 2 * gap)}px`,
    );
    tip.style.setProperty("--pantoken-tooltip-gap", `${gap}px`);
    const anchor = wrapper.getBoundingClientRect();
    const bubble = tip.getBoundingClientRect();
    const rtl = style.direction === "rtl";
    const preferred = tip.classList.contains("-placement-bottom")
      ? "bottom"
      : tip.classList.contains("-placement-start")
        ? rtl
          ? "right"
          : "left"
        : tip.classList.contains("-placement-end")
          ? rtl
            ? "left"
            : "right"
          : "top";
    const opposite = { top: "bottom", bottom: "top", left: "right", right: "left" } as const;
    const room = {
      top: anchor.top - top,
      bottom: bottom - anchor.bottom,
      left: anchor.left - left,
      right: right - anchor.right,
    };
    const needed = {
      top: bubble.height + gap,
      bottom: bubble.height + gap,
      left: bubble.width + gap,
      right: bubble.width + gap,
    };
    const sides = [preferred, opposite[preferred], "top", "bottom", "left", "right"] as const;
    const side =
      sides.find((candidate) => room[candidate] >= needed[candidate]) ??
      sides.reduce(
        (best, candidate) =>
          room[candidate] - needed[candidate] > room[best] - needed[best] ? candidate : best,
        preferred,
      );
    const centerX = anchor.left + (anchor.width - bubble.width) / 2;
    const centerY = anchor.top + (anchor.height - bubble.height) / 2;
    const positions = {
      top: { x: centerX, y: anchor.top - bubble.height - gap },
      bottom: { x: centerX, y: anchor.bottom + gap },
      left: { x: anchor.left - bubble.width - gap, y: centerY },
      right: { x: anchor.right + gap, y: centerY },
    };
    const { x, y } = positions[side];
    tip.style.left = `${Math.max(left, Math.min(x, right - bubble.width)) - anchor.left - wrapper.clientLeft + wrapper.scrollLeft}px`;
    tip.style.top = `${Math.max(top, Math.min(y, bottom - bubble.height)) - anchor.top - wrapper.clientTop + wrapper.scrollTop}px`;
    tip.style.right = "auto";
    tip.style.bottom = "auto";
    for (const property of ["margin-top", "margin-right", "margin-bottom", "margin-left"])
      tip.style.setProperty(property, "0px");
    tip.style.transform = "none";
    tip.setAttribute("data-tooltip-side", side);
  };
  const isWithin = (target: EventTarget | null): boolean =>
    target instanceof Node &&
    (wrapper.contains(target) ||
      [...wrapper.querySelectorAll("slot")].some((slot) =>
        slot.assignedNodes({ flatten: true }).some((node) => node.contains(target)),
      ));
  let hovering = wrapper.matches(":hover");
  let focused = isWithin(document.activeElement) || wrapper.matches(":focus-within");
  let dismissed = false;
  let cleaned = false;
  wrapper.setAttribute("data-tooltip-managed", "");

  const update = () => {
    clearTimeout(timer);
    if (!hovering && !focused) {
      dismissed = false;
      timer = setTimeout(() => tip.classList.remove("-show"), options?.hideDelay ?? 0);
    } else if (!dismissed && !tip.classList.contains("-show")) {
      timer = setTimeout(() => {
        tip.classList.add("-show");
        position();
      }, options?.showDelay ?? 0);
    }
  };
  let previousPointer: { x: number; y: number } | undefined;
  let traveling = false;
  const corridor = (point: { x: number; y: number }) => {
    const side = tip.getAttribute("data-tooltip-side");
    if (side !== "top" && side !== "bottom" && side !== "left" && side !== "right") return;
    const anchor = wrapper.getBoundingClientRect();
    const bubble = tip.getBoundingClientRect();
    const vertical = side === "top" || side === "bottom";
    const edges = {
      top: [anchor.bottom, bubble.bottom],
      bottom: [anchor.top, bubble.top],
      left: [anchor.right, bubble.right],
      right: [anchor.left, bubble.left],
    } as const;
    const [start, end] = edges[side];
    const along = vertical ? point.y : point.x;
    const across = vertical ? point.x : point.y;
    const progress = (along - start) / (end - start);
    const fromLow = vertical ? anchor.left : anchor.top;
    const fromHigh = vertical ? anchor.right : anchor.bottom;
    const toLow = vertical ? bubble.left : bubble.top;
    const toHigh = vertical ? bubble.right : bubble.bottom;
    return {
      inside:
        progress >= 0 &&
        progress <= 1 &&
        across >= fromLow + (toLow - fromLow) * progress &&
        across <= fromHigh + (toHigh - fromHigh) * progress,
      distance: Math.abs(end - along),
    };
  };
  const stopTravel = () => {
    document.removeEventListener("pointermove", onTravel);
    document.removeEventListener("pointerout", onTravelOut);
    traveling = false;
  };
  const onTravelOut = (event: PointerEvent) => {
    if (event.relatedTarget) return;
    stopTravel();
    hovering = false;
    update();
  };
  const onTravel = (event: PointerEvent) => {
    const point = { x: event.clientX, y: event.clientY };
    if (previousPointer?.x === point.x && previousPointer.y === point.y) return;
    const from = previousPointer && corridor(previousPointer);
    const to = corridor(point);
    if (from && to?.inside && to.distance < from.distance) {
      previousPointer = point;
      return;
    }
    stopTravel();
    hovering = false;
    update();
  };
  const cancelAndHide = () => {
    clearTimeout(timer);
    if (traveling) {
      stopTravel();
      hovering = false;
    }
    dismissed = hovering || focused;
    tip.classList.remove("-show");
  };
  const onPointerEnter = (event: PointerEvent) => {
    stopTravel();
    previousPointer =
      event instanceof view.PointerEvent ? { x: event.clientX, y: event.clientY } : undefined;
    hovering = true;
    update();
  };
  const onPointerMove = (event: PointerEvent) => {
    previousPointer = { x: event.clientX, y: event.clientY };
  };
  const onPointerLeave = (event: PointerEvent) => {
    const point = { x: event.clientX, y: event.clientY };
    const from = previousPointer && corridor(previousPointer);
    const to = corridor(point);
    if (
      event instanceof view.PointerEvent &&
      event.pointerType !== "touch" &&
      tip.classList.contains("-show") &&
      from &&
      to?.inside &&
      to.distance < from.distance
    ) {
      traveling = true;
      previousPointer = point;
      document.addEventListener("pointermove", onTravel);
      document.addEventListener("pointerout", onTravelOut);
      return;
    }
    stopTravel();
    hovering = false;
    update();
  };
  const onFocusIn = () => {
    if (focused) return;
    focused = true;
    update();
  };
  const onFocusOut = (event: FocusEvent) => {
    if (isWithin(event.relatedTarget)) return;
    focused = false;
    update();
  };
  const onKeydown = (e: KeyboardEvent) => {
    if (e.key === "Escape") cancelAndHide();
  };

  wrapper.addEventListener("pointerenter", onPointerEnter);
  wrapper.addEventListener("pointerleave", onPointerLeave);
  wrapper.addEventListener("pointermove", onPointerMove);
  wrapper.addEventListener("focusin", onFocusIn);
  wrapper.addEventListener("focusout", onFocusOut);
  document.addEventListener("keydown", onKeydown);
  view.addEventListener("resize", position);
  const roots: (Document | ShadowRoot)[] = [document];
  for (
    let root = wrapper.getRootNode();
    root instanceof view.ShadowRoot;
    root = root.host.getRootNode()
  )
    roots.push(root);
  for (const root of roots) root.addEventListener("scroll", position, true);
  view.visualViewport?.addEventListener("resize", position);
  view.visualViewport?.addEventListener("scroll", position);
  const resize = new view.ResizeObserver(position);
  resize.observe(wrapper);
  resize.observe(tip);
  const mutations = new view.MutationObserver(position);
  mutations.observe(tip, {
    attributes: true,
    attributeFilter: ["class"],
    childList: true,
    characterData: true,
    subtree: true,
  });
  for (const root of roots)
    mutations.observe(root, { attributes: true, attributeFilter: ["dir"], subtree: true });
  if (hovering || focused) update();

  return {
    cancelAndHide,
    cleanup: () => {
      if (cleaned) return;
      cleaned = true;
      clearTimeout(timer);
      wrapper.removeEventListener("pointerenter", onPointerEnter);
      wrapper.removeEventListener("pointerleave", onPointerLeave);
      wrapper.removeEventListener("pointermove", onPointerMove);
      stopTravel();
      wrapper.removeEventListener("focusin", onFocusIn);
      wrapper.removeEventListener("focusout", onFocusOut);
      document.removeEventListener("keydown", onKeydown);
      view.removeEventListener("resize", position);
      for (const root of roots) root.removeEventListener("scroll", position, true);
      view.visualViewport?.removeEventListener("resize", position);
      view.visualViewport?.removeEventListener("scroll", position);
      resize.disconnect();
      mutations.disconnect();
      restorePosition();
      if (originalManaged === null) wrapper.removeAttribute("data-tooltip-managed");
      else wrapper.setAttribute("data-tooltip-managed", originalManaged);
      tip.classList.toggle("-show", originalShown);
    },
  };
}

/**
 * @component tooltip
 * @selector .instui-tooltip
 * @summary Visibility styling for the tooltip web component's tip — hidden until the component reveals it.
 * @remarks For a larger, click-triggered anchored surface, see the [popover](/api/css/popover.md) component.
 * @part .tip — The floating tip surface.
 * @cssstate show — The tip is revealed (opaque and visible); without it the tip is hidden.
 * @accessibility The tip is a `role="tooltip"` revealed on both hover and focus, so keyboard users reach it; set its text via the `tip` attribute.
 * @example
 * <instui-tooltip tip="Save your work" placement="bottom">
 *   <button class="instui-button">Save</button>
 * </instui-tooltip>
 * @structure
 * .instui-tooltip {
 *   slot {}
 *   .tip {}
 * }
 * @demo self:tooltip
 */
.instui-tooltip > .tip:not(.-show) {
  opacity: 0 !important;
  visibility: hidden !important;
}

.instui-tooltip > .tip.-show {
  opacity: 1;
  visibility: visible;
}

/**
 * @component tooltip
 * @selector .pfx-tooltip
 * @summary A hover and focus tooltip bubble, positionable on any side.
 * @remarks Load `@pantoken/interactions/tooltip.iife.js` for managed delays, Escape dismissal, and combined pointer/focus state. Without JavaScript, hover/focus remains a fallback without Escape or delay guarantees. Use a popover for interactive content.
 * @modifier -icon-* — Render a trigger glyph icon next to the tooltip bubble.
 * @part .tip — The bubble; `-placement-*` sets its preferred side. Initialized tooltips flip/clamp to fit the viewport.
 * @a11y Use a named, focusable trigger with aria-describedby pointing at the role="tooltip" bubble. Keep the content noninteractive. Initialized tooltips stay dismissed after Escape until both pointer and focus leave; the next entry can reopen them.
 * @demo self:tooltip
 * @example -canvas-rce
 * ```html
 * <span class="pfx-tooltip">
 *   <button class="pfx-icon-button" type="button" aria-label="Information" aria-describedby="tt-1">
 *     <span class="pfx-icon -icon-info" aria-hidden="true"></span>
 *   </button>
 *   <span class="tip" id="tt-1" role="tooltip">Default placement is top</span>
 * </span>
 * ```
 * @example -automatica11y
 * ```html
 * <p style="padding-block: 3rem">
 * <span class="pfx-tooltip">
 *   <button type="button" aria-describedby="help-tip" data-a11y-trigger>Help</button>
 *   <span class="tip -show" id="help-tip" role="tooltip" data-a11y-root>Find answers.</span>
 * </span>
 * </p>
 * <p style="padding-block: 3rem"><span class="pfx-tooltip"><button type="button" aria-describedby="bottom-tip">Bottom help</button><span class="tip -placement-bottom -show" id="bottom-tip" role="tooltip">Find answers.</span></span></p>
 * <p style="padding-block: 3rem"><span class="pfx-tooltip"><button type="button" aria-describedby="start-tip">Start help</button><span class="tip -placement-start -show" id="start-tip" role="tooltip">Find answers.</span></span></p>
 * <p style="padding-block: 3rem"><span class="pfx-tooltip"><button type="button" aria-describedby="end-tip">End help</button><span class="tip -placement-end -show" id="end-tip" role="tooltip">Find answers.</span></span></p>
 * ```
 * @example -docs
 * ```html
 * <span class="pfx-tooltip">
 *   <button class="pfx-button" type="button" aria-describedby="placement-tip">Placement</button>
 *   <span class="tip -placement-bottom" id="placement-tip" role="tooltip">This tooltip appears below.</span>
 * </span>
 * ```
 * @structure
 * .pfx-tooltip {
 *   [class*="-icon-"]:optional {}
 *   .tip {}
 * }
 * @related popover — The larger, click-triggered anchored surface.
 * @related context-view — A related anchored surface with a pointer.
 */
@scope (.pfx-tooltip) {
  :scope {
    position: relative;
    display: inline-flex;

    > :is([class^="-icon-"], [class*=" -icon-"]) {
      line-height: 1;
    }

    > .tip {
      position: absolute;
      box-sizing: border-box;
      inline-size: max-content;
      max-inline-size: min(
        24rem,
        var(
          --pantoken-tooltip-viewport-inline-size,
          calc(100vw - 2 * var(--instui-spacing-space-xs))
        )
      );
      z-index: 1;
      inset-block-end: 100%;
      inset-inline-start: 50%;
      transform: translateX(-50%);
      margin-block-end: var(--instui-spacing-space-xs);
      padding: var(--instui-component-tooltip-padding);
      background: var(--instui-color-background-inverse);
      color: var(--instui-color-text-inverse);
      border-radius: var(--instui-border-radius-sm);
      font-family: var(--instui-component-tooltip-font-family);
      font-size: var(--instui-component-tooltip-font-size);
      font-weight: var(--instui-component-tooltip-font-weight);
      white-space: normal;
      overflow-wrap: anywhere;
      opacity: 0;
      visibility: hidden;
      pointer-events: auto;
      @media (prefers-reduced-motion: no-preference) {
        transition: opacity 0.15s ease;
      }

      /* Bridge the visual gap so moving from trigger to bubble doesn't leave the wrapper. */
      &::before {
        content: "";
        position: absolute;
        inset-inline: 0;
        inset-block-start: 100%;
        block-size: var(--instui-spacing-space-xs);
      }

      /* translateX is physical while the inset is logical, so RTL needs the opposite sign to stay centered. */
      &:dir(rtl) {
        transform: translateX(50%);
      }

      /* Placement (authored on the .tip itself, matching the web-component): default is top; these move the
         bubble to the other sides. */
      &.-placement-bottom {
        inset-block: 100% auto;
        margin-block: var(--instui-spacing-space-xs) 0;

        &::before {
          inset-block: auto 100%;
        }
      }

      &.-placement-start {
        inset-block-end: auto;
        inset-inline: auto 100%;
        top: 50%;
