import { mkdirSync, readFileSync, writeFileSync } from "node:fs";
import { dirname, resolve } from "node:path";

const root = resolve(import.meta.dirname, "../../..");
const sourcePath = resolve(root, "ai/pantoken-ai/catalogs/pantoken-v1.json");
const outputs = [
  resolve(root, "renderers/web-components/src/generated/a2ui-catalog.json"),
  resolve(root, "docs/.vitepress/theme/generated/a2ui-catalog.json"),
  resolve(root, "docs/public/a2ui/catalog.json"),
];

const allowedComponents = {
  PantokenButton: {
    properties: ["action", "component", "label", "variant"],
    required: ["component", "label"],
    enums: {
      variant: ["primary", "secondary", "tertiary", "success", "danger", "ai", "ai-secondary"],
    },
    selector: "PantokenButton",
  },
  PantokenTooltip: {
    properties: ["action", "component", "placement", "tip", "triggerLabel"],
    required: ["component", "triggerLabel", "tip", "action"],
    enums: { placement: ["top", "bottom", "start", "end"] },
    selector: "PantokenTooltip",
  },
} as const;

type JsonRecord = Record<string, unknown>;

function isRecord(value: unknown): value is JsonRecord {
  return value !== null && typeof value === "object" && !Array.isArray(value);
}

function fail(message: string): never {
  throw new Error(`Invalid Pantoken A2UI catalog: ${message}`);
}

/** Reject catalog changes that exceed the published A2UI v1 component contract. */
export function validateCatalog(value: unknown): asserts value is JsonRecord {
  if (!isRecord(value)) fail("expected an object");
  if (value.protocolVersion !== "1.0") fail("protocolVersion must be 1.0");
  if (
    value.catalogId !== "https://pantoken.app/a2ui/catalog/v1/catalog.json" ||
    value.$id !== value.catalogId
  ) {
    fail("catalogId and $id must use the versioned v1 catalog URI");
  }
  const components = value.components;
  if (!isRecord(components)) fail("components must be an object");
  if ("functions" in value) fail("Pantoken does not publish executable catalog functions");

  const componentNames = Object.keys(allowedComponents);
  if (
    Object.keys(components).length !== componentNames.length ||
    componentNames.some((name) => !(name in components))
  ) {
    fail(`components must be exactly ${componentNames.join(", ")}`);
  }

  for (const [name, contract] of Object.entries(allowedComponents)) {
    const component = components[name];
    if (!isRecord(component) || !isRecord(component.properties)) {
      fail(`${name} must declare a properties object`);
    }
    if (component.additionalProperties !== false) {
      fail(`${name} must reject properties outside its allowlist`);
    }
    const properties = component.properties;
    const selector = properties.component;
    if (!isRecord(selector) || selector.const !== contract.selector) {
      fail(`${name}.component must be the ${contract.selector} constant`);
    }
    const propertyNames = Object.keys(properties).sort();
    if (propertyNames.join(",") !== [...contract.properties].sort().join(",")) {
      fail(`${name} properties must be exactly ${contract.properties.join(", ")}`);
    }
    const required = component.required;
    if (
      !Array.isArray(required) ||
      required.length !== contract.required.length ||
      !contract.required.every((property) => required.includes(property))
    ) {
      fail(`${name} required properties must be exactly ${contract.required.join(", ")}`);
    }
    for (const [property, values] of Object.entries(contract.enums)) {
      const definition = properties[property];
      if (
        !isRecord(definition) ||
        definition.type !== "string" ||
        !Array.isArray(definition.enum)
      ) {
        fail(`${name}.${property} must be an enum`);
      }
      if (definition.enum.join(",") !== values.join(",")) {
        fail(`${name}.${property} enum does not match the renderer allowlist`);
      }
    }
    for (const property of ["label", "triggerLabel", "tip"]) {
      if (!(property in properties)) continue;
      const definition = properties[property];
      if (!isRecord(definition) || definition.$ref !== "common_types.json#/$defs/DynamicString") {
        fail(`${name}.${property} must use A2UI v1.0 DynamicString`);
      }
    }
    if ("action" in properties) {
      const definition = properties.action;
      if (!isRecord(definition) || definition.$ref !== "common_types.json#/$defs/Action") {
        fail(`${name}.action must use the A2UI v1.0 Action contract`);
      }
    }
  }
}

/** Validate the canonical schema and write or verify its runtime and documentation copies. */
export function generateA2uiCatalog(check: boolean = process.argv.includes("--check")): void {
  const source = readFileSync(sourcePath, "utf8");
  const parsed: unknown = JSON.parse(source);
  validateCatalog(parsed);
  const output = `${JSON.stringify(parsed, null, 2)}\n`;

  for (const path of outputs) {
    if (check) {
      let existing: string;
      try {
        existing = readFileSync(path, "utf8");
      } catch (error) {
        if (error instanceof Error && "code" in error && error.code === "ENOENT") {
          throw new Error(`Generated A2UI catalog is missing: ${path}`);
        }
        throw error;
      }
      if (existing !== output) throw new Error(`Generated A2UI catalog is stale: ${path}`);
      continue;
    }
    mkdirSync(dirname(path), { recursive: true });
    writeFileSync(path, output);
  }
}

if (import.meta.url === `file://${process.argv[1]}`) {
  generateA2uiCatalog();
}

/**
 * The registry of element definitions. {@link DEFINITIONS} lists them in the canonical registration
 * order (load-bearing: nesting elements like `date-input` assume `calendar` and `date-time-input`
 * assume `date-input` are defined, and the parity test asserts this exact order). `register()` in the
 * package barrel builds the shared context once and calls each definition's `define`.
 *
 * @module
 */
import type { ElementDefinition } from "../lib/context.ts";
import { alert } from "./alert.ts";
import { avatar } from "./avatar.ts";
import { badge } from "./badge.ts";
import { button } from "./button.ts";
import { calendar } from "./calendar.ts";
import { contextView } from "./context-view.ts";
import { dateInput } from "./date-input.ts";
import { dateTimeInput } from "./date-time-input.ts";
import { drawerLayout } from "./drawer-layout.ts";
import { drilldown } from "./drilldown.ts";
import { icon } from "./icon.ts";
import { iconButton } from "./icon-button.ts";
import { img } from "./img.ts";
import { inPlaceEdit } from "./in-place-edit.ts";
import { metric } from "./metric.ts";
import { modal } from "./modal.ts";
import { pages } from "./pages.ts";
import { pill } from "./pill.ts";
import { popover } from "./popover.ts";
import { progress } from "./progress.ts";
import { progressCircle } from "./progress-circle.ts";
import { rating } from "./rating.ts";
import { sideNavBar } from "./side-nav-bar.ts";
import { spinner } from "./spinner.ts";
import { tag } from "./tag.ts";
import { tabs } from "./tabs.ts";
import { toggleButton } from "./toggle-button.ts";
import { tooltip } from "./tooltip.ts";
import { tray } from "./tray.ts";
import { treeBrowser } from "./tree-browser.ts";
import { truncate } from "./truncate.ts";

/**
 * Every element definition, in the canonical registration order. The order is load-bearing:
 * `date-input` renders a nested `calendar` and `date-time-input` renders a nested `date-input`, and
 * the `ELEMENTS` tuple / the register-order test both derive from this list.
 */
export const DEFINITIONS: readonly ElementDefinition[] = [
  icon,
  button,
  alert,
  badge,
  pill,
  tag,
  avatar,
  spinner,
  progress,
  metric,
  rating,
  progressCircle,
  iconButton,
  toggleButton,
  truncate,
  img,
  sideNavBar,
  treeBrowser,
  calendar,
  tooltip,
  modal,
  contextView,
  popover,
  tray,
  inPlaceEdit,
  drilldown,
  pages,
  drawerLayout,
  dateInput,
  dateTimeInput,
  tabs,
];

/**
 * Shared types for the web-components registry: the structural registry adapter, the Invoker
 * Commands event shape, and the {@link RegisterContext}/{@link ElementDefinition} contract that lets
 * every element live in its own file yet register through one shared, prefix-aware pipeline.
 *
 * @module
 */
import type { WebComponentStrings } from "./strings.ts";
import type { OnCommand } from "@pantoken/interactions";

/** A minimal structural type for a custom-element registry (the DOM's `customElements`). */
export interface ElementRegistry {
  get(name: string): unknown;
  define(name: string, ctor: CustomElementConstructor): void;
}

export type { CommandEventish } from "@pantoken/interactions";

/**
 * The shared state a `register()` call builds once and threads to every {@link ElementDefinition}.
 * It carries the prefix-aware registry adapter, the `tag()` helper for nested markup, the CSS-class
 * prefix `I`, the Invoker Commands support flag + router, the `wrapper`/`variantClass`/`iconSvg`
 * factories, and locale data (`strings`, `locale`, `dir`, `firstDay`).
 */
export interface RegisterContext {
  /** The scoped registry: rewrites `instui-<base>` → the active-prefix tag on `get`/`define`. */
  registry: ElementRegistry;
  /** Map a base name to the active-prefix tag (for nested markup, `querySelector`, `tagName`). */
  tag: (base: string) => string;
  /** The CSS-class prefix for the inlined component sheets — always `instui`, separate from the tag prefix. */
  I: { readonly prefix: "instui" };
  /** Whether the browser supports the Invoker Commands API (`command`/`commandfor`). */
  invokerSupported: boolean;
  /** Route a target's `command` events (or a click fallback) to a handler. */
  onCommand: OnCommand;
  /** Define a shadow-DOM element: `<style>:host{display}css</style>` + markup from `render(host)`.
   * `invoker: true` forwards the host's `popovertarget`/`command` to the inner `<button>` (IDL). */
  wrapper: (
    tag: string,
    css: string,
    render: (host: HTMLElement) => string,
    options?: { display?: string; invoker?: boolean },
  ) => void;
  /** Build a `.instui-<name>` class with an optional `-color-<variant>` modifier from `variant`. */
  variantClass: (name: string, host: HTMLElement) => string;
  /** Resolve an icon name to inline SVG (empty string when unknown). */
  iconSvg: (name: string) => string;
  /** BCP47 locale tag used for `toLocaleDateString` and `Intl` formatting. */
  locale: string;
  /** Text direction derived from the active locale bundle. */
  dir: "ltr" | "rtl";
  /** First day of week as JS `Date.getDay()` index (0=Sunday … 6=Saturday). */
  firstDay: number;
  /** Translated UI strings for all behavioral elements. */
  strings: WebComponentStrings;
}

/** One registered custom element: its base tag name plus a `define` that registers it via the context. */
export interface ElementDefinition {
  /** The base tag name, e.g. `button` (minted to `<instui-button>`/`<x-button>` by the active prefix). */
  readonly name: string;
  /** Register the element into `ctx.registry`, using only the shared, prefix-aware helpers. */
  define(ctx: RegisterContext): void;
}

