import { trayCss } from "@pantoken/components";
import type { ElementDefinition } from "../lib/context.ts";
import popoverReset from "../lib/popover-reset.css?inline";

/**
 * `<instui-tray>` — a panel docked to a viewport edge, backed by a native `[popover]` (top layer +
 * light-dismiss). `placement` maps to `-placement-<value>` (e.g. `start`, `end`, `top`, `bottom`) and
 * `size` to `-size-<value>`; a light-DOM `popovertarget` button toggles it by id. Content goes in the
 * default slot.
 *
 * @example
 * ```html
 * <button popovertarget="nav">Menu</button>
 * <instui-tray id="nav" placement="start" size="small">…</instui-tray>
 * ```
 */
export const tray: ElementDefinition = {
  name: "tray",
  define: (ctx) => {
    if (ctx.registry.get("instui-tray")) return;
    ctx.registry.define(
      "instui-tray",
      class extends HTMLElement {
        static observedAttributes = ["placement", "size"];
        constructor() {
          super();
          this.attachShadow({ mode: "open" });
        }
        connectedCallback(): void {
          if (!this.hasAttribute("popover")) this.setAttribute("popover", "auto");
          this.paint();
        }
        attributeChangedCallback(): void {
          this.paint();
        }
        paint(): void {
          const root = this.shadowRoot;
          if (!root) return;
          const parts = ["instui-tray"];
          const placement = (this.getAttribute("placement") ?? "").replace(/[^a-z-]/giu, "");
          const size = (this.getAttribute("size") ?? "").replace(/[^a-z]/giu, "");
          if (placement) parts.push(`-placement-${placement}`);
          if (size) parts.push(`-size-${size}`);
          root.innerHTML = `<style>${popoverReset}${trayCss(ctx.I)}</style><div class="${parts.join(" ")}" part="tray"><slot></slot></div>`;
        }
      },
    );
  },
};

import { inPlaceEditCss } from "@pantoken/components";
import { initInPlaceEdit } from "@pantoken/interactions";
import type { InPlaceEditInputType } from "@pantoken/interactions";
import type { ElementDefinition } from "../lib/context.ts";
import { esc } from "../lib/helpers.ts";

const INPUT_TYPES = new Set<InPlaceEditInputType>([
  "text",
  "number",
  "email",
  "url",
  "tel",
  "search",
]);

/**
 * `<instui-in-place-edit>` — a click-to-edit field. `value` shows as text; on click/focus it becomes
 * editable, Enter or blur commits (and fires a bubbling `change` event with `detail.value`), and
 * Escape reverts to the pre-edit value. `readonly` disables editing. An external `value` change
 * reflects into the field while it isn't being edited. `input-type` accepts `text`, `number`,
 * `email`, `url`, `tel`, or `search` as a non-validating editing hint.
 *
 * @example
 * ```html
 * <instui-in-place-edit value="Course title"></instui-in-place-edit>
 * ```
 */
export const inPlaceEdit: ElementDefinition = {
  name: "in-place-edit",
  define: (ctx) => {
    if (ctx.registry.get("instui-in-place-edit")) return;
    ctx.registry.define(
      "instui-in-place-edit",
      class extends HTMLElement {
        static observedAttributes = ["value", "readonly"];
        #field: HTMLElement | null = null;
        constructor() {
          super();
          this.attachShadow({ mode: "open" });
        }
        connectedCallback(): void {
          const root = this.shadowRoot;
          if (!root) return;
          const readonly = this.hasAttribute("readonly");
          const value = esc(this.getAttribute("value") ?? this.textContent ?? "");
          root.innerHTML =
            `<style>:host{display:inline-block}${inPlaceEditCss(ctx.I)}</style>` +
            `<span class="instui-in-place-edit${readonly ? " -readonly" : ""}" part="field" role="textbox"` +
            ` contenteditable="${readonly ? "false" : "true"}">${value}</span>`;
          const field = root.querySelector<HTMLElement>(".instui-in-place-edit");
          this.#field = field;
          if (!field || readonly) return;
          const inputType = this.getAttribute("input-type") as InPlaceEditInputType | null;
          initInPlaceEdit(field, this, {
            inputType: inputType && INPUT_TYPES.has(inputType) ? inputType : undefined,
          });
        }
        attributeChangedCallback(name: string): void {
          // Reflect an external value change into the field when it isn't being edited.
          if (name === "value" && this.#field && this.shadowRoot?.activeElement !== this.#field) {
            this.#field.textContent = this.getAttribute("value") ?? "";
          }
        }
      },
    );
  },
};

import { menuCss } from "@pantoken/components";
import type { ElementDefinition } from "../lib/context.ts";
import drilldownExtra from "./drilldown.css?inline";
import { esc } from "../lib/helpers.ts";

/**
 * `<instui-drilldown>` — a stateful, multi-level menu over the menu styles. Each level is a light-DOM
 * `[data-page="id"]` whose inner `.item`s are cloned into a shadow `.instui-menu`; an item with
 * `data-goto="id"` descends to that page and a synthesized Back row (or any `[data-back]` item)
 * returns. The light DOM is the data source only — with no `<slot>` it never renders, so shadow CSS
 * fully styles each panel. The `active` attribute reflects the current page and can be set to
 * navigate; a bubbling `navigate` event (`detail.page`) fires on every move. Drivable from light DOM
 * via Invoker Commands: `<button command="--goto" commandfor="dd-id" data-page="…">` descends and
 * `<button command="--back" commandfor="dd-id">` returns.
 *
 * @example
 * ```html
 * <instui-drilldown active="root">
 *   <div data-page="root">
 *     <div class="item" data-goto="settings">Settings</div>
 *   </div>
 *   <div data-page="settings">
 *     <div class="item">Profile</div>
 *   </div>
 * </instui-drilldown>
 * ```
 */
export const drilldown: ElementDefinition = {
  name: "drilldown",
  define: (ctx) => {
    if (ctx.registry.get("instui-drilldown")) return;
    ctx.registry.define(
      "instui-drilldown",
      class extends HTMLElement {
        static observedAttributes = ["active"];
        #stack: string[] = [];
        #wired = false;
        constructor() {
          super();
          this.attachShadow({ mode: "open" });
        }
        connectedCallback(): void {
          const first =
            this.getAttribute("active") ??
            this.querySelector("[data-page]")?.getAttribute("data-page") ??
            "";
          this.#stack = first ? [first] : [];
          // Drivable from light DOM via Invoker Commands: `<button command="--goto" commandfor="dd-id"
          // data-page="…">` descends and `command="--back" commandfor="dd-id">` returns. (In-panel item
          // navigation stays click/keydown-delegated, since those items are your own markup.)
          if (!this.#wired) {
            this.#wired = true;
            ctx.onCommand(this, (command, source) => {
              if (command === "--back") this.back();
              else if (command === "--goto") {
                const page = source?.getAttribute("data-page");
                if (page) this.push(page);
              }
            });
          }
          this.paint();
        }
        attributeChangedCallback(name: string, _old: string | null, value: string | null): void {
          // An external `active` change reseeds the stack; ignored when it already matches the top
          // (which is the case for our own push/back writes, so they don't recurse).
          if (name === "active" && value && value !== this.#stack[this.#stack.length - 1]) {
            this.#stack = [value];
            this.paint();
          }
        }
        #pages(): Map<string, string> {
          const pages = new Map<string, string>();
          for (const el of this.querySelectorAll("[data-page]")) {
            pages.set(el.getAttribute("data-page") ?? "", el.innerHTML);
          }
          return pages;
        }
        push(id: string): void {
          if (!this.#pages().has(id)) return;
          this.#stack.push(id);
          this.setAttribute("active", id);
          this.paint();
          this.dispatchEvent(new CustomEvent("navigate", { detail: { page: id }, bubbles: true }));
        }
        back(): void {
          if (this.#stack.length <= 1) return;
          this.#stack.pop();
          const to = this.#stack[this.#stack.length - 1] ?? "";
          this.setAttribute("active", to);
          this.paint();
          this.dispatchEvent(new CustomEvent("navigate", { detail: { page: to }, bubbles: true }));
        }
        paint(): void {
          const root = this.shadowRoot;
          if (!root || !this.isConnected) return;
          const current = this.#stack[this.#stack.length - 1] ?? "";
          const body = this.#pages().get(current) ?? "";
          const backRow =
            this.#stack.length > 1
              ? `<div class="item -drilldown-back" role="menuitem" tabindex="0">${ctx.iconSvg(ctx.dir === "rtl" ? "arrow-right" : "arrow-left")}<span>${esc(ctx.strings.back)}</span></div><div class="separator"></div>`
              : "";
          root.innerHTML =
            `<style>:host{display:inline-block}${menuCss(ctx.I)}${drilldownExtra}</style>` +
            `<div class="instui-menu" part="drilldown" role="menu">${backRow}${body}</div>`;
          const menu = root.querySelector<HTMLElement>(".instui-menu");
          const hit = (target: EventTarget | null): HTMLElement | null =>
            (target as HTMLElement | null)?.closest<HTMLElement>(
              "[data-goto],[data-back],.-drilldown-back",
            ) ?? null;
          menu?.addEventListener("click", (event) => {
            const item = hit(event.target);
            if (!item) return;
            if (item.hasAttribute("data-back") || item.classList.contains("-drilldown-back")) {
              this.back();
            } else {
              const to = item.getAttribute("data-goto");
              if (to) this.push(to);
            }
          });
          menu?.addEventListener("keydown", (event) => {
            if (event.key === "Enter" || event.key === " ") {
              const item = hit(event.target);
              if (item) {
                event.preventDefault();
                item.click();
              }
            } else if (event.key === "Escape" || event.key === "ArrowLeft") {
              this.back();
            }
          });
        }
      },
    );
  },
};

import type { ElementDefinition } from "../lib/context.ts";
import pagesCss from "./pages.css?inline";

/**
 * `<instui-pages>` — shows one slotted `[data-page]` panel at a time, swapping with the View
 * Transitions API when available (a plain toggle otherwise). `push(id)`/`back()` keep a history
 * stack; the `active` attribute reflects the current page and can be set to navigate, and a bubbling
 * `change` event (`detail.page`) fires per swap. Drivable from light DOM via Invoker Commands:
 * `<button command="--push" commandfor="pages-id" data-page="…">` and
 * `<button command="--back" commandfor="pages-id">`.
 *
 * @example
 * ```html
 * <instui-pages active="one">
 *   <section data-page="one">First <button command="--push" commandfor="p" data-page="two">Next</button></section>
 *   <section data-page="two">Second <button command="--back" commandfor="p">Back</button></section>
 * </instui-pages>
 * ```
 */
export const pages: ElementDefinition = {
  name: "pages",
  define: (ctx) => {
    if (ctx.registry.get("instui-pages")) return;
    ctx.registry.define(
      "instui-pages",
      class extends HTMLElement {
        static observedAttributes = ["active"];
        #stack: string[] = [];
        constructor() {
          super();
          this.attachShadow({ mode: "open" });
        }
        connectedCallback(): void {
          const root = this.shadowRoot;
          if (root && !root.querySelector("slot")) {
            root.innerHTML = `<style>${pagesCss}</style><slot></slot>`;
            // Drivable from light DOM via Invoker Commands: `<button command="--push" commandfor="pages-id"
            // data-page="…">` and `command="--back" commandfor="pages-id">`.
            ctx.onCommand(this, (command, source) => {
              if (command === "--push") {
                const page = source?.getAttribute("data-page");
                if (page) this.push(page);
              } else if (command === "--back") this.back();
            });
          }
          const first =
            this.getAttribute("active") ??
            this.querySelector("[data-page]")?.getAttribute("data-page") ??
            "";
          this.#stack = first ? [first] : [];
          this.#apply();
        }
        attributeChangedCallback(name: string, _old: string | null, value: string | null): void {
          if (name === "active" && value && value !== this.#stack[this.#stack.length - 1]) {
            this.#stack = [value];
            this.#apply();
          }
        }
        #panels(): HTMLElement[] {
          return [...this.querySelectorAll<HTMLElement>("[data-page]")];
        }
        #apply(): void {
          if (!this.isConnected) return;
          const current = this.#stack[this.#stack.length - 1] ?? "";
          const swap = (): void => {
            for (const panel of this.#panels()) {
              panel.hidden = panel.getAttribute("data-page") !== current;
            }
          };
          const doc = document as Document & { startViewTransition?: (cb: () => void) => unknown };
          if (typeof doc.startViewTransition === "function") doc.startViewTransition(swap);
          else swap();
          this.dispatchEvent(
            new CustomEvent("change", { detail: { page: current }, bubbles: true }),
          );
        }
        push(id: string): void {
          if (!this.#panels().some((panel) => panel.getAttribute("data-page") === id)) return;
          this.#stack.push(id);
          this.setAttribute("active", id);
          this.#apply();
        }
        back(): void {
          if (this.#stack.length <= 1) return;
          this.#stack.pop();
          this.setAttribute("active", this.#stack[this.#stack.length - 1] ?? "");
          this.#apply();
        }
      },
    );
  },
};

import { drawerLayoutContentCss, drawerLayoutCss, drawerLayoutTrayCss } from "@pantoken/components";
import { initResponsiveOverlay } from "@pantoken/interactions";
import type { ElementDefinition } from "../lib/context.ts";
import DRAWER_CSS from "./drawer-layout.css?inline";

/**
 * `<instui-drawer-layout>` — a side tray plus main content area. The `open` attribute reveals the
 * tray; `placement` (`start`|`end`) picks the side. Drivable from light DOM via Invoker Commands:
 * `<button command="--toggle|--open|--close" commandfor="drawer-id">`. Content goes in the default
 * slot; the tray in `slot="tray"`. The interactions behavior auto-toggles overlay mode based on the
 * `--pantoken-bp-md` threshold.
 *
 * @accessibility Both panes are `div` regions, matching InstUI's inline DrawerLayout. Supply nonempty `tray-label` and `content-label` attributes to name them; labels on the host or slotted content don't name the shadow-DOM regions.
 * @example
 * ```html
 * <button command="--toggle" commandfor="drawer">Toggle panel</button>
 * <instui-drawer-layout id="drawer" open placement="start" tray-label="Course panel" content-label="Course content">
 *   <nav slot="tray" aria-label="Course sections">…</nav>
 *   <article>Main content</article>
 * </instui-drawer-layout>
 * ```
 */
export const drawerLayout: ElementDefinition = {
  name: "drawer-layout",
  define: (ctx) => {
    if (ctx.registry.get("instui-drawer-layout")) return;
    ctx.registry.define(
      "instui-drawer-layout",
      class extends HTMLElement {
        static observedAttributes = [
          "open",
          "placement",
          "should-overlay-tray",
          "tray-label",
          "content-label",
        ];
        constructor() {
          super();
          this.attachShadow({ mode: "open" });
        }
        connectedCallback(): void {
          const root = this.shadowRoot;
          if (!root || root.querySelector(".layout")) return;

          const style =
            drawerLayoutCss(ctx.I) +
            drawerLayoutTrayCss(ctx.I) +
            drawerLayoutContentCss(ctx.I) +
            DRAWER_CSS;

          const styleEl = document.createElement("style");
          styleEl.textContent = style;

          const layout = document.createElement("div");
          layout.className = `layout ${ctx.I.prefix}-drawer-layout`;

          const tray = document.createElement("div");
          tray.className = "tray";
