      placement: "center",
      action,
    }).success,
  ).toBe(false);
  expect(
    tooltip?.schema.safeParse({
      triggerLabel: "Help",
      tip: "More information",
      href: "javascript:alert(1)",
      action,
    }).success,
  ).toBe(false);
  expect(pantokenA2uiCatalog.components.has("UnknownComponent")).toBe(false);
