          const min = Number.isFinite(rawMin) ? rawMin : 0;
          const rawMax = Number(
            this.getAttribute("value-max") ?? this.getAttribute("max") ?? "100",
          );
          const max = Number.isFinite(rawMax) && rawMax > min ? rawMax : Math.max(100, min + 100);
          const rawValue = Number(
            this.getAttribute("value-now") ?? this.getAttribute("value") ?? String(min),
          );
          const value = Math.max(min, Math.min(max, Number.isFinite(rawValue) ? rawValue : min));
          const rawDelay = Number(this.getAttribute("animation-delay") ?? "0");
          const delay = Number.isFinite(rawDelay) && rawDelay >= 0 ? rawDelay : 0;
          return { value, min, max, delay };
        }

        #paint(): void {
          const root = this.shadowRoot;
          if (!root) return;
          const { value, min, max, delay } = this.#values();
          const percentage = ((value - min) / (max - min)) * 100;
          const label = esc(this.getAttribute("label") ?? `${String(percentage)}%`);
          const animate = this.hasAttribute("should-animate") && !this.#hasAnimated;
          const tag = min === 0 ? "progress" : "meter";
          const minAttribute = tag === "meter" ? ` min="${String(min)}"` : "";
          root.innerHTML =
            `<style>:host{display:inline-block}.native{position:absolute;inline-size:1px;block-size:1px;overflow:hidden;clip-path:inset(50%)}${progressCircleCss(ctx.I)}</style>` +
            `<${tag} class="native" value="${String(value)}"${minAttribute} max="${String(max)}" aria-label="${label}" part="native"></${tag}>` +
            `<span class="instui-progress-circle${animate ? " -should-animate" : ""}" aria-hidden="true" part="progress-circle" style="--value:${String(value)};--min:${String(min)};--max:${String(max)};--animation-delay:${String(delay)}"></span>`;
        }

        #startAnimation(): void {
          const ring = this.shadowRoot?.querySelector<HTMLElement>(".instui-progress-circle");
          if (!ring?.classList.contains("-should-animate")) return;
          this.#hasAnimated = true;
          this.#animationHandle = initProgressCircle(ring, {
            animationDelay: this.#values().delay,
          });
        }
      },
    );
  },
};

import { ratingCss } from "@pantoken/components";
import type { ElementDefinition } from "../lib/context.ts";
import { esc } from "../lib/helpers.ts";

/**
 * `<instui-rating>` — a star rating with `role="img"`. `value` is the number of filled stars, `max`
 * the total (default 5), and `label` overrides the accessible name (defaults to `value/max`). Stars
 * render as inline SVG glyphs (solid = filled), sized to the text.
 *
 * @example
 * ```html
 * <instui-rating value="4" max="5" label="4 out of 5 stars"></instui-rating>
 * ```
 */
export const rating: ElementDefinition = {
  name: "rating",
  define: (ctx) =>
    // Rating renders star glyphs as inline SVG (solid = filled, outline = empty); the rating CSS colours
    // the filled ones. A small appended rule sizes the SVGs to the text (1em), and a `.label` shows the
    // value. (The CSS glyph painter isn't inlined here, so we embed the SVG directly.)
    ctx.wrapper(
      "instui-rating",
      `${ratingCss(ctx.I)}\n.instui-rating svg{inline-size:1em;block-size:1em}`,
      (host) => {
        const value = Math.max(0, Number(host.getAttribute("value") ?? "0"));
        const max = Math.max(1, Number(host.getAttribute("max") ?? "5"));
        const label = esc(host.getAttribute("label") ?? `${String(value)}/${String(max)}`);
        const stars = Array.from({ length: max }, (_, i) => {
          const solid = i < value;
          const cls = solid ? "instui-icon -icon-star-solid" : "instui-icon -icon-star";
          return `<span class="${cls}" style="display:inline-flex">${ctx.iconSvg(solid ? "star-solid" : "star")}</span>`;
        }).join("");
        return `<span class="instui-rating" role="img" aria-label="${label}" part="rating">${stars}<span class="label">${label}</span></span>`;
      },
    ),
};

import { metricCss } from "@pantoken/components";
import type { ElementDefinition } from "../lib/context.ts";
import { esc } from "../lib/helpers.ts";

/**
 * `<instui-metric>` — a labelled statistic: a large `value` over a smaller `label`. Both come from
 * attributes (escaped), not slots.
 *
 * @example
 * ```html
 * <instui-metric value="1,024" label="Enrolled"></instui-metric>
 * ```
 */
export const metric: ElementDefinition = {
  name: "metric",
  define: (ctx) =>
    ctx.wrapper("instui-metric", metricCss(ctx.I), (host) => {
      const value = esc(host.getAttribute("value") ?? "");
      const label = esc(host.getAttribute("label") ?? "");
      return `<div class="instui-metric" part="metric"><span class="value">${value}</span><span class="label">${label}</span></div>`;
    }),
};

import { defineComponent, type Definition } from "../../lib/define.ts";
import { SENTINEL } from "../../lib/sentinel.ts";
import { tabs as tabsRaw } from "../../generated/component-styles.ts";

/** The `tabs` component record: a tabbed panel set with a tab list, selectable tabs, and their panels. */
export const tabs: Definition = defineComponent({
  name: "tabs",
  css: (p) => tabsRaw.replaceAll(SENTINEL, p),
});
/** Standalone `tabs` stylesheet — the prefixed CSS for the tabbed panels, ready to ship as a `.css` file. */
export const tabsCss: Definition["css"] = tabs.css;

import { inPlaceEditCss } from "@pantoken/components";
import { initInPlaceEdit } from "@pantoken/interactions";
import type { InPlaceEditInputType } from "@pantoken/interactions";
import type { ElementDefinition } from "../lib/context.ts";
import { esc } from "../lib/helpers.ts";

const INPUT_TYPES = new Set<InPlaceEditInputType>([
  "text",
  "number",
  "email",
  "url",
  "tel",
  "search",
]);

/**
 * `<instui-in-place-edit>` — a click-to-edit field. `value` shows as text; on click/focus it becomes
 * editable, Enter or blur commits (and fires a bubbling `change` event with `detail.value`), and
 * Escape reverts to the pre-edit value. `readonly` disables editing. An external `value` change
 * reflects into the field while it isn't being edited. `input-type` accepts `text`, `number`,
 * `email`, `url`, `tel`, or `search` as a non-validating editing hint.
 *
 * @example
 * ```html
 * <instui-in-place-edit value="Course title"></instui-in-place-edit>
 * ```
 */
export const inPlaceEdit: ElementDefinition = {
  name: "in-place-edit",
  define: (ctx) => {
    if (ctx.registry.get("instui-in-place-edit")) return;
    ctx.registry.define(
      "instui-in-place-edit",
      class extends HTMLElement {
        static observedAttributes = ["value", "readonly"];
        #field: HTMLElement | null = null;
        constructor() {
          super();
          this.attachShadow({ mode: "open" });
        }
        connectedCallback(): void {
          const root = this.shadowRoot;
          if (!root) return;
          const readonly = this.hasAttribute("readonly");
          const value = esc(this.getAttribute("value") ?? this.textContent ?? "");
          root.innerHTML =
            `<style>:host{display:inline-block}${inPlaceEditCss(ctx.I)}</style>` +
            `<span class="instui-in-place-edit${readonly ? " -readonly" : ""}" part="field" role="textbox"` +
            ` contenteditable="${readonly ? "false" : "true"}">${value}</span>`;
          const field = root.querySelector<HTMLElement>(".instui-in-place-edit");
          this.#field = field;
          if (!field || readonly) return;
          const inputType = this.getAttribute("input-type") as InPlaceEditInputType | null;
          initInPlaceEdit(field, this, {
            inputType: inputType && INPUT_TYPES.has(inputType) ? inputType : undefined,
          });
        }
        attributeChangedCallback(name: string): void {
          // Reflect an external value change into the field when it isn't being edited.
          if (name === "value" && this.#field && this.shadowRoot?.activeElement !== this.#field) {
            this.#field.textContent = this.getAttribute("value") ?? "";
          }
        }
      },
    );
  },
};

/** Controls the listeners installed by {@link initTabs}. */
export interface TabsHandle {
  cleanup(): void;
}

/** Wire a tablist and its controlled panels inside a host element. */
export function initTabs(host: HTMLElement): TabsHandle {
  const tabs = (): HTMLButtonElement[] => [
    ...host.querySelectorAll<HTMLButtonElement>('[role="tab"]'),
  ];

  const select = (tab: HTMLButtonElement): void => {
    for (const other of tabs()) {
      const selected = other === tab;
      other.classList.toggle("-selected", selected);
      other.setAttribute("aria-selected", String(selected));
      const panelId = other.getAttribute("aria-controls");
      const panel = panelId ? document.getElementById(panelId) : undefined;
      if (panel) panel.hidden = !selected;
    }
  };

  const onClick = (event: Event): void => {
    const tab = (event.target as Element | null)?.closest<HTMLButtonElement>('[role="tab"]');
    if (tab && host.contains(tab) && !tab.disabled) select(tab);
  };

  const onKeyDown = (event: KeyboardEvent): void => {
    const tab = (event.target as Element | null)?.closest<HTMLButtonElement>('[role="tab"]');
    if (!tab || !host.contains(tab) || tab.disabled) return;

    const available = tabs().filter((candidate) => !candidate.disabled);
    const index = available.indexOf(tab);
    let nextIndex = index;
    if (event.key === "ArrowRight") nextIndex = (index + 1) % available.length;
    else if (event.key === "ArrowLeft")
      nextIndex = (index - 1 + available.length) % available.length;
    else if (event.key === "Home") nextIndex = 0;
    else if (event.key === "End") nextIndex = available.length - 1;
    else if (event.key === "Enter" || event.key === " ") {
      event.preventDefault();
      select(tab);
      return;
    } else return;

    event.preventDefault();
    available[nextIndex]?.focus();
    select(available[nextIndex]);
  };

  host.addEventListener("click", onClick);
  host.addEventListener("keydown", onKeyDown);

  const initial =
    tabs().find(
      (tab) => tab.classList.contains("-selected") || tab.getAttribute("aria-selected") === "true",
    ) ?? tabs()[0];
  if (initial) select(initial);

  return {
    cleanup(): void {
      host.removeEventListener("click", onClick);
      host.removeEventListener("keydown", onKeyDown);
    },
  };
}

import type { OnCommand } from "../shared/index.js";

/**
 * Wire a CSS `<dialog class="instui-modal">` or a web component's shadow
 * `<dialog>` to the `open` attribute protocol and `--show/--close/--toggle`
 * command routing. Both usages pass the same interface:
 *
 * - CSS: `host === dialog` (the dialog itself carries the id and open attr)
 * - WC: `host` = custom element, `dialog` = its shadow `<dialog>`
 */
export function initModal(
  host: HTMLElement,
  dialog: HTMLDialogElement,
  onCommand: OnCommand,
): void {
  const setOpen = (wantOpen: boolean): void => {
    const modal = dialog.matches(":modal");
    if (wantOpen && !modal) {
      // An authored open attribute creates a nonmodal dialog; promote it through showModal().
      if (dialog.open) dialog.removeAttribute("open");
      dialog.showModal();
    } else if (!wantOpen && (dialog.open || modal)) {
      // Removing open doesn't leave the top layer. Restore it so native close can finish.
      if (!dialog.open) dialog.setAttribute("open", "");
      dialog.close();
    } else if (wantOpen && !dialog.open) {
      dialog.setAttribute("open", "");
    }
    if (host !== dialog) host.toggleAttribute("open", dialog.open);
  };
  const sync = (): void => setOpen(host.hasAttribute("open"));

  dialog.addEventListener("close", () => {
    // A native close event may arrive after the dialog has already reopened.
    if (!dialog.open && host.hasAttribute("open")) host.removeAttribute("open");
    // Only re-dispatch when host ≠ dialog (web component); for CSS use host IS dialog.
    if (host !== dialog) host.dispatchEvent(new CustomEvent("close", { bubbles: true }));
  });

  onCommand(host, (command) => {
    if (command === "--show") setOpen(true);
    else if (command === "--close") setOpen(false);
    else if (command === "--toggle") setOpen(!host.hasAttribute("open"));
  });

  new MutationObserver(sync).observe(host, { attributes: true, attributeFilter: ["open"] });
  sync();
}

import { trayCss } from "@pantoken/components";
import type { ElementDefinition } from "../lib/context.ts";
import popoverReset from "../lib/popover-reset.css?inline";

/**
 * `<instui-tray>` — a panel docked to a viewport edge, backed by a native `[popover]` (top layer +
 * light-dismiss). `placement` maps to `-placement-<value>` (e.g. `start`, `end`, `top`, `bottom`) and
 * `size` to `-size-<value>`; a light-DOM `popovertarget` button toggles it by id. Content goes in the
 * default slot.
 *
 * @example
 * ```html
 * <button popovertarget="nav">Menu</button>
 * <instui-tray id="nav" placement="start" size="small">…</instui-tray>
 * ```
 */
export const tray: ElementDefinition = {
  name: "tray",
  define: (ctx) => {
    if (ctx.registry.get("instui-tray")) return;
    ctx.registry.define(
      "instui-tray",
      class extends HTMLElement {
        static observedAttributes = ["placement", "size"];
        constructor() {
          super();
          this.attachShadow({ mode: "open" });
        }
        connectedCallback(): void {
          if (!this.hasAttribute("popover")) this.setAttribute("popover", "auto");
          this.paint();
        }
        attributeChangedCallback(): void {
          this.paint();
        }
        paint(): void {
          const root = this.shadowRoot;
          if (!root) return;
          const parts = ["instui-tray"];
          const placement = (this.getAttribute("placement") ?? "").replace(/[^a-z-]/giu, "");
          const size = (this.getAttribute("size") ?? "").replace(/[^a-z]/giu, "");
          if (placement) parts.push(`-placement-${placement}`);
          if (size) parts.push(`-size-${size}`);
          root.innerHTML = `<style>${popoverReset}${trayCss(ctx.I)}</style><div class="${parts.join(" ")}" part="tray"><slot></slot></div>`;
        }
      },
    );
  },
};

import { tooltipCss } from "@pantoken/components";
import { initTooltip } from "@pantoken/interactions";
import type { ElementDefinition } from "../lib/context.ts";
import tooltipGate from "./tooltip.css?inline";
import { frag } from "../lib/helpers.ts";

/**
 * `<instui-tooltip>` — wraps a slotted trigger and shows a `.tip` bubble (from the `tip` attribute)
 * on hover/focus. `placement` maps to `-placement-<value>` (e.g. `bottom`, `end`); `show-delay` and
 * `hide-delay` (ms, default 0) gate the reveal/hide. Shared behavior owns visibility; Escape
 * dismisses until both pointer and focus leave. Tooltip content is noninteractive.
 *
 * @example
 * ```html
 * <instui-tooltip tip="Placement bottom" placement="bottom" show-delay="200">
 *   <button class="instui-button -color-secondary">Hover me</button>
 * </instui-tooltip>
 * ```
 */
export const tooltip: ElementDefinition = {
  name: "tooltip",
  define: (ctx) => {
    if (ctx.registry.get("instui-tooltip")) return;
    ctx.registry.define(
      "instui-tooltip",
      class extends HTMLElement {
        static observedAttributes = ["tip", "placement", "show-delay", "hide-delay"];
        #handle: { cleanup(): void; cancelAndHide(): void } | undefined;
        #bubble: HTMLElement | null = null;
        #options = { showDelay: 0, hideDelay: 0 };
        constructor() {
          super();
          this.attachShadow({ mode: "open" });
        }
        connectedCallback(): void {
          this.paint();
        }
        attributeChangedCallback(): void {
          this.paint();
        }
        disconnectedCallback(): void {
          this.#handle?.cleanup();
          this.#handle = undefined;
        }
        paint(): void {
          const root = this.shadowRoot;
          if (!root) return;
          const placement = frag(this.getAttribute("placement"));
          const tipCls = placement ? `tip -placement-${placement}` : "tip";
          if (!this.#bubble) {
            root.innerHTML =
              `<style>:host{display:inline-flex}${tooltipCss(ctx.I)}${tooltipGate}</style>` +
              `<span class="instui-tooltip" part="tooltip"><slot></slot>` +
              `<span class="tip" role="tooltip"></span></span>`;
            this.#bubble = root.querySelector<HTMLElement>(".tip");
          }
          const wrap = root.querySelector<HTMLElement>(".instui-tooltip");
          if (!wrap || !this.#bubble) return;
          const shown = this.#bubble.classList.contains("-show");
          this.#bubble.className = tipCls;
          this.#bubble.classList.toggle("-show", shown);
          this.#bubble.textContent = this.getAttribute("tip") ?? "";
          this.#options.showDelay = Number(this.getAttribute("show-delay")) || 0;
          this.#options.hideDelay = Number(this.getAttribute("hide-delay")) || 0;
          // Retain interaction state across attribute updates, especially Escape dismissal.
          if (this.isConnected && !this.#handle)
            this.#handle = initTooltip(wrap, this.#bubble, this.#options);
        }
      },
    );
  },
};

import { buttonCss, calendarCss } from "@pantoken/components";
import type { ElementDefinition } from "../lib/context.ts";
import calendarReset from "./calendar.css?inline";
import { esc, isoDate, parseIsoDate } from "../lib/helpers.ts";

/**
 * `<instui-calendar>` — an interactive month grid. `value` (`yyyy-mm-dd`) is the selected day and
 * `view` (`yyyy-mm-dd`, optional) the visible month. The prev/next chevrons and every day are
 * `<button>`s driving the Invoker Commands API (`--calendar-prev`, `--calendar-next`,
 * `--calendar-select`) at the grid; selecting a day updates `value`/`view` and dispatches a composed,
 * bubbling `change` event (`detail.value` is the ISO date). Renders its own grid (no slot), so it
 * works standalone or nested inside a date picker.
 *
 * @example
 * ```html
 * <instui-calendar value="2026-07-08"></instui-calendar>
 * ```
 */
export const calendar: ElementDefinition = {
  name: "calendar",
  define: (ctx) => {
    if (ctx.registry.get("instui-calendar")) return;
    ctx.registry.define(
      "instui-calendar",
      class extends HTMLElement {
        static observedAttributes = ["value", "view"];
        constructor() {
          super();
          this.attachShadow({ mode: "open" });
        }
        connectedCallback(): void {
          this.paint();
        }
        attributeChangedCallback(): void {
          this.paint();
        }
        #shiftMonth(delta: number): void {
          const base =
            parseIsoDate(this.getAttribute("view") ?? "") ??
            parseIsoDate(this.getAttribute("value") ?? "") ??
            new Date();
          this.setAttribute(
            "view",
            isoDate(new Date(base.getFullYear(), base.getMonth() + delta, 1)),
          );
        }
        #select(value: string): void {
          this.setAttribute("value", value);
          this.setAttribute("view", value);
          this.dispatchEvent(
            new CustomEvent("change", { detail: { value }, bubbles: true, composed: true }),
          );
        }
        paint(): void {
          const root = this.shadowRoot;
          if (!root) return;
          const selected = this.getAttribute("value") ?? "";
          const view =
            parseIsoDate(this.getAttribute("view") ?? "") ?? parseIsoDate(selected) ?? new Date();
          const year = view.getFullYear();
          const month = view.getMonth();
          const label = view.toLocaleDateString(ctx.locale, { month: "long", year: "numeric" });
          const today = isoDate(new Date());
          // Leading blank cells: offset from the locale's first-day-of-week.
          const lead = (new Date(year, month, 1).getDay() - ctx.firstDay + 7) % 7;
          const total = new Date(year, month + 1, 0).getDate();
          const cells: Date[] = [];
          for (let i = 0; i < lead; i++) cells.push(new Date(year, month, 1 - (lead - i)));
          for (let d = 1; d <= total; d++) cells.push(new Date(year, month, d));
          for (let d = 1; cells.length % 7 !== 0; d++) cells.push(new Date(year, month + 1, d));
          const dayHtml = cells
            .map((date) => {
              const iso = isoDate(date);
              const classes = ["day"];
              if (date.getMonth() !== month) classes.push("-outside-month");
              if (iso === today) classes.push("-today");
              if (iso === selected) classes.push("-selected");
              const current = iso === selected ? ' aria-current="date"' : "";
              return `<button type="button" class="${classes.join(" ")}" data-value="${iso}" command="--calendar-select" commandfor="cal"${current}>${String(date.getDate())}</button>`;
            })
            .join("");
          const weekdays = ctx.strings.weekdays
            .map((w) => `<span class="weekday">${esc(w)}</span>`)
            .join("");
          root.innerHTML =
            `<style>:host{display:inline-block}${calendarCss(ctx.I)}${buttonCss(ctx.I)}${calendarReset}</style>` +
            `<div class="instui-calendar" id="cal" role="group" aria-label="${esc(label)}" part="calendar">` +
            `<div class="nav">` +
            `<button type="button" class="instui-button -color-tertiary -shape-square -without-border" command="--calendar-prev" commandfor="cal" aria-label="${esc(ctx.strings.prevMonth)}">${ctx.iconSvg(ctx.dir === "rtl" ? "chevron-right" : "chevron-left")}</button>` +
            `<strong>${esc(label)}</strong>` +
            `<button type="button" class="instui-button -color-tertiary -shape-square -without-border" command="--calendar-next" commandfor="cal" aria-label="${esc(ctx.strings.nextMonth)}">${ctx.iconSvg(ctx.dir === "rtl" ? "chevron-left" : "chevron-right")}</button>` +
            `</div>` +
            `<div class="grid">${weekdays}${dayHtml}</div>` +
            `</div>`;
          const cal = root.getElementById("cal");
          if (cal) {
            ctx.onCommand(cal, (command, source) => {
              if (command === "--calendar-prev") this.#shiftMonth(-1);
              else if (command === "--calendar-next") this.#shiftMonth(1);
              else if (command === "--calendar-select") {
                const value = source?.getAttribute("data-value");
                if (value) this.#select(value);
              }
            });
          }
        }
      },
    );
  },
};

