 *   <div class="list" role="tablist" aria-label="Settings">
 *     <button role="tab" aria-selected="true" aria-controls="general">General</button>
 *     <button role="tab" aria-selected="false" aria-controls="advanced">Advanced</button>
 *   </div>
 *   <div id="general" role="tabpanel">General settings</div>
 *   <div id="advanced" role="tabpanel" hidden>Advanced settings</div>
 * </instui-tabs>
 * ```
 */
export const tabs: ElementDefinition = {
  name: "tabs",
  define: (ctx) => {
    if (ctx.registry.get("instui-tabs")) return;
    ctx.registry.define(
      "instui-tabs",
      class extends HTMLElement {
        #handle: TabsHandle | undefined;

        connectedCallback(): void {
          this.classList.add("instui-tabs");
          this.#handle = initTabs(this);
        }

        disconnectedCallback(): void {
          this.#handle?.cleanup();
          this.#handle = undefined;
        }
      },
    );
  },
};

/**
 * Shared types for the web-components registry: the structural registry adapter, the Invoker
 * Commands event shape, and the {@link RegisterContext}/{@link ElementDefinition} contract that lets
 * every element live in its own file yet register through one shared, prefix-aware pipeline.
 *
 * @module
 */
import type { WebComponentStrings } from "./strings.ts";
import type { OnCommand } from "@pantoken/interactions";

/** A minimal structural type for a custom-element registry (the DOM's `customElements`). */
export interface ElementRegistry {
  get(name: string): unknown;
  define(name: string, ctor: CustomElementConstructor): void;
}

export type { CommandEventish } from "@pantoken/interactions";

/**
 * The shared state a `register()` call builds once and threads to every {@link ElementDefinition}.
 * It carries the prefix-aware registry adapter, the `tag()` helper for nested markup, the CSS-class
 * prefix `I`, the Invoker Commands support flag + router, the `wrapper`/`variantClass`/`iconSvg`
 * factories, and locale data (`strings`, `locale`, `dir`, `firstDay`).
 */
export interface RegisterContext {
  /** The scoped registry: rewrites `instui-<base>` → the active-prefix tag on `get`/`define`. */
  registry: ElementRegistry;
  /** Map a base name to the active-prefix tag (for nested markup, `querySelector`, `tagName`). */
  tag: (base: string) => string;
  /** The CSS-class prefix for the inlined component sheets — always `instui`, separate from the tag prefix. */
  I: { readonly prefix: "instui" };
  /** Whether the browser supports the Invoker Commands API (`command`/`commandfor`). */
  invokerSupported: boolean;
  /** Route a target's `command` events (or a click fallback) to a handler. */
  onCommand: OnCommand;
  /** Define a shadow-DOM element: `<style>:host{display}css</style>` + markup from `render(host)`.
   * `invoker: true` forwards the host's `popovertarget`/`command` to the inner `<button>` (IDL). */
  wrapper: (
    tag: string,
    css: string,
    render: (host: HTMLElement) => string,
    options?: { display?: string; invoker?: boolean },
  ) => void;
  /** Build a `.instui-<name>` class with an optional `-color-<variant>` modifier from `variant`. */
  variantClass: (name: string, host: HTMLElement) => string;
  /** Resolve an icon name to inline SVG (empty string when unknown). */
  iconSvg: (name: string) => string;
  /** BCP47 locale tag used for `toLocaleDateString` and `Intl` formatting. */
  locale: string;
  /** Text direction derived from the active locale bundle. */
  dir: "ltr" | "rtl";
  /** First day of week as JS `Date.getDay()` index (0=Sunday … 6=Saturday). */
  firstDay: number;
  /** Translated UI strings for all behavioral elements. */
  strings: WebComponentStrings;
}

/** One registered custom element: its base tag name plus a `define` that registers it via the context. */
export interface ElementDefinition {
  /** The base tag name, e.g. `button` (minted to `<instui-button>`/`<x-button>` by the active prefix). */
  readonly name: string;
  /** Register the element into `ctx.registry`, using only the shared, prefix-aware helpers. */
  define(ctx: RegisterContext): void;
}

import { icons } from "@pantoken/icons";
import { ELEMENTS } from "./lib/elements-meta.ts";

type JsonSchema = Record<string, unknown>;
type ElementName = (typeof ELEMENTS)[number];
type AttributeMode = "boolean" | "boolean-string" | "media-url" | "popover-open";

/** A safe A2UI schema and rendering mapping for one Pantoken property. */
export interface A2uiPropertyContract {
  schema: JsonSchema;
  attribute?: string;
  mode?: AttributeMode;
  minimum?: number;
  maximum?: number;
}

/** Maps a Pantoken interaction event to an A2UI property update. */
export interface A2uiValueChange {
  event: string;
  property: string;
  detailProperty?: string;
  kind?: "toggle" | "tab-index" | "close" | "popover-state";
}

/** The A2UI schema and rendering behavior for one exported web component. */
export interface A2uiComponentContract {
  description: string;
  properties?: Record<string, A2uiPropertyContract>;
  required?: readonly string[];
  contentProperty?: string;
  children?: "slot" | "tree" | "pages" | "tabs" | "drawer";
  special?: "icon-button" | "tooltip" | "tree" | "pages" | "tabs" | "drilldown" | "drawer";
  actionEvents?: readonly string[];
  valueChange?: A2uiValueChange;
  attributeChange?: { attribute: string; property: string };
}

const REFS = {
  action: "common_types.json#/$defs/Action",
  boolean: "common_types.json#/$defs/DynamicBoolean",
  childList: "common_types.json#/$defs/ChildList",
  componentId: "common_types.json#/$defs/ComponentId",
  mediaUrl: "common_types.json#/$defs/MediaUrl",
  number: "common_types.json#/$defs/DynamicNumber",
  string: "common_types.json#/$defs/DynamicString",
} as const;

const dynamicString: JsonSchema = { $ref: REFS.string };
const dynamicNumber: JsonSchema = { $ref: REFS.number };
const dynamicBoolean: JsonSchema = { $ref: REFS.boolean };
const childList: JsonSchema = { $ref: REFS.childList, minItems: 1, maxItems: 32 };
const action: JsonSchema = { $ref: REFS.action };
const componentId: JsonSchema = { $ref: REFS.componentId };
const mediaUrl: JsonSchema = { $ref: REFS.mediaUrl };
const iconNames = icons.map(({ name }) => name);

function property(
  schema: JsonSchema,
  attribute?: string,
  mode?: AttributeMode,
  bounds?: { minimum?: number; maximum?: number },
): A2uiPropertyContract {
  return {
    schema,
    ...(attribute ? { attribute } : {}),
    ...(mode ? { mode } : {}),
    ...bounds,
  };
}

function text(attribute?: string): A2uiPropertyContract {
  return property(dynamicString, attribute);
}

function number(
  attribute: string,
  bounds?: { minimum?: number; maximum?: number },
): A2uiPropertyContract {
  return property(dynamicNumber, attribute, undefined, bounds);
}

function boolean(
  attribute: string,
  mode: "boolean" | "boolean-string" = "boolean",
): A2uiPropertyContract {
  return property(dynamicBoolean, attribute, mode);
}

function enumeration(
  values: readonly string[],
  attribute?: string,
  defaultValue?: string,
): A2uiPropertyContract {
  return property(
    {
      type: "string",
      enum: [...values],
      ...(defaultValue ? { default: defaultValue } : {}),
    },
    attribute,
  );
}

function schemaEnum(values: readonly string[]): JsonSchema {
  return { type: "string", enum: [...values] };
}

function listOf(items: JsonSchema, minimum: number, maximum: number): JsonSchema {
  return { type: "array", items, minItems: minimum, maxItems: maximum };
}

const buttonVariants = [
  "primary",
  "secondary",
  "tertiary",
  "danger",
  "success",
  "ai",
  "ai-secondary",
] as const;

const drilldownPageId = { type: "string", pattern: "^[A-Za-z0-9_-]{1,64}$" };
const drilldownPages: JsonSchema = {
  type: "array",
  minItems: 1,
  maxItems: 32,
  items: {
    type: "object",
    properties: {
      id: drilldownPageId,
      items: {
        type: "array",
        minItems: 1,
        maxItems: 64,
        items: {
          type: "object",
          properties: {
            back: dynamicBoolean,
            label: dynamicString,
            target: drilldownPageId,
          },
          required: ["label"],
          additionalProperties: false,
        },
      },
    },
    required: ["id", "items"],
    additionalProperties: false,
  },
};

/** Contracts are exhaustive against ELEMENTS; adding a web component requires an explicit A2UI contract. */
export const A2UI_COMPONENTS: Record<ElementName, A2uiComponentContract> = {
  icon: {
    description: "An inline glyph selected from Pantoken's icon set.",
    properties: {
      name: property(schemaEnum(iconNames), "name"),
      size: enumeration(["1em", "1.25em", "1.5em", "2em"], "size", "1em"),
    },
    required: ["name"],
  },
  button: {
    description:
      "A token-styled action button with optional A2UI event and Invoker Commands behavior.",
    properties: {
      label: text(),
      variant: enumeration(buttonVariants, "variant", "primary"),
      commandTarget: property(componentId, "commandfor"),
      command: enumeration(
        ["--show", "--close", "--toggle", "--push", "--back", "--goto"],
        "command",
      ),
      popoverTarget: property(componentId, "popovertarget"),
      popoverAction: enumeration(["toggle", "show", "hide"], "popovertargetaction"),
    },
    required: ["label"],
    contentProperty: "label",
    children: "slot",
    actionEvents: ["click"],
  },

        const content = contract.contentProperty
          ? (props[contract.contentProperty] ?? nothing)
          : nothing;
        values.push(
          html`<instui-button variant="secondary"
            >${renderChildNodes(this.renderNode.bind(this), children)}${content}</instui-button
          >`,
        );
      } else {
        const children = contract.children === "slot" ? childRefs(props.children) : [];
        const renderedChildren = renderChildNodes(this.renderNode.bind(this), children);
        const content = contract.contentProperty
          ? (props[contract.contentProperty] ?? nothing)
          : nothing;
        values.push(html`${renderedChildren}${content}`);
      }
      return html(genericTemplate.strings, ...values);
    }

    protected override updated(changed: PropertyValues): void {
      super.updated(changed);
      const host =
        contract.special === "tooltip"
          ? this.renderRoot.querySelector<HTMLElement>("button")
          : this.renderRoot.querySelector<HTMLElement>(`instui-${element}`);
      if (host !== this.#component) {
        this.#observer?.disconnect();
        this.#component?.removeEventListener("click", this.#onComponentEvent);
        for (const event of new Set([
          ...(contract.actionEvents ?? []),
          ...(contract.valueChange ? [contract.valueChange.event] : []),
        ])) {
          this.#component?.removeEventListener(event, this.#onComponentEvent);
        }
        this.#component = host;
        if (host) {
          for (const event of new Set([
            ...(contract.actionEvents ?? []),
            ...(contract.valueChange ? [contract.valueChange.event] : []),
          ])) {
            host.addEventListener(event, this.#onComponentEvent);
          }
          if (contract.attributeChange) {
            this.#observer = new MutationObserver(() => {
              const props = this.controller.props;
              const setter = setterFor(props, contract.attributeChange!.property);
              const value = host.hasAttribute(contract.attributeChange!.attribute);
              if (value !== props[contract.attributeChange!.property]) setter?.(value);
            });
            this.#observer.observe(host, {
              attributes: true,
              attributeFilter: [contract.attributeChange.attribute],
            });
          }
        }
      }
      if (contract.special === "tooltip") {
        const wrapper = this.renderRoot.querySelector<HTMLElement>(".instui-tooltip");
        const tip = wrapper?.querySelector<HTMLElement>('[role="tooltip"]');
        const props = this.controller.props;
        const options = {
          showDelay: typeof props.showDelay === "number" ? props.showDelay : 0,
          hideDelay: typeof props.hideDelay === "number" ? props.hideDelay : 0,
        };
        if (
          wrapper &&
          tip &&
          (this.#tooltipOptions?.showDelay !== options.showDelay ||
            this.#tooltipOptions?.hideDelay !== options.hideDelay)
        ) {
          this.#tooltipHandle?.cleanup();
          this.#tooltipHandle = initTooltip(wrapper, tip, options);
          this.#tooltipOptions = options;
        }
      }
      this.#syncPopover(host);
    }

    #syncPopover(host: HTMLElement | null): void {
      const openProperty = Object.entries(contract.properties ?? {}).find(
        ([, definition]) => definition.mode === "popover-open",
      );
      if (!host || !openProperty) return;
      const [propertyName] = openProperty;
      const requested = this.controller.props[propertyName];
      if (typeof requested !== "boolean") return;
      if (this.#popoverOpen === undefined) {
        if (requested) this.#setPopoverState(host, true);
        this.#popoverOpen = requested;
      } else if (requested !== this.#popoverOpen) {
        this.#setPopoverState(host, requested);
        this.#popoverOpen = requested;
      }
    }

    #setPopoverState(host: HTMLElement, open: boolean): void {
      const popover = host as HTMLElement & {
        showPopover?: () => void;
        hidePopover?: () => void;
      };
      const change = open ? popover.showPopover : popover.hidePopover;
      if (typeof change !== "function") {
        throw new Error(
          `Pantoken ${element} requires the browser Popover API to bind its open state.`,
        );
      }
      change.call(host);
    }

    override disconnectedCallback(): void {
      super.disconnectedCallback();
      this.#observer?.disconnect();
      this.#observer = undefined;
      this.#tooltipHandle?.cleanup();
      this.#tooltipHandle = undefined;
      this.#tooltipOptions = undefined;
      for (const event of new Set([
        ...(contract.actionEvents ?? []),
        ...(contract.valueChange ? [contract.valueChange.event] : []),
      ])) {
        this.#component?.removeEventListener(event, this.#onComponentEvent);
      }
      this.#component = null;
    }
  }

  Object.defineProperty(PantokenA2uiElement, "name", {
    value: `PantokenA2ui${a2uiNameForElement(element).slice("Pantoken".length)}Element`,
  });
  return PantokenA2uiElement;
}

/** A Universal A2UI implementation for every exported Pantoken web component. */
export const pantokenA2uiComponents: PantokenA2uiImplementation[] = ELEMENTS.map((element) => {
  const name = a2uiNameForElement(element);
  const api = getApi(name);
  return {
    ...api,
    tagName: `pantoken-a2ui-${element}`,
    element: createA2uiElement(element, api),
  };
});

/** The runtime A2UI catalog containing all Pantoken v1 web-component implementations. */
export const pantokenA2uiCatalog: Catalog<ComponentApi> = new Catalog(
  PANTOKEN_A2UI_CATALOG_ID,
  "1.0",
  pantokenA2uiComponents,
  [],
  {
    schemaUri: "https://json-schema.org/draft/2020-12/schema",
    schemaId: PANTOKEN_A2UI_CATALOG_ID,
    title: "Pantoken A2UI Catalog",
    description: "A constrained set of Pantoken-styled components for A2UI v1.0 web clients.",
    declaredProtocolVersion: "1.0",
  },
);

/** Register all Pantoken web components and their A2UI Universal adapters on demand. */
export function registerPantokenA2uiComponents(): void {
  if (!globalThis.customElements || typeof HTMLElement === "undefined") return;
  const context = buildRegisterContext({}, globalThis.customElements, iconSvg);
  for (const definition of DEFINITIONS) definition.define(context);
  for (const component of pantokenA2uiComponents) registerUniversalElement(component);
}

