  const wrapper = element.shadowRoot?.querySelector<HTMLElement>(".instui-tooltip");
  const tip = wrapper?.querySelector<HTMLElement>('[role="tooltip"]');
  wrapper?.dispatchEvent(new Event("pointerenter"));
