/** Return the versioned A2UI catalog name for an exported web component. */
export function a2uiNameForElement(element: ElementName): string {
  return `Pantoken${element
    .split("-")
    .map((part) => part.slice(0, 1).toUpperCase() + part.slice(1))
    .join("")}`;
}

/** Build the catalog properties for a component contract. */
export function a2uiPropertiesFor(contract: A2uiComponentContract): Record<string, JsonSchema> {
  const properties = Object.fromEntries(
    Object.entries(contract.properties ?? {}).map(([name, definition]) => {
      const schema = {
        ...definition.schema,
        ...(definition.minimum !== undefined ? { minimum: definition.minimum } : {}),
        ...(definition.maximum !== undefined ? { maximum: definition.maximum } : {}),
      };
      return [name, schema];
    }),
  );
  if (contract.children) properties.children = childList;
  if (contract.actionEvents?.length) properties.action = action;
  return properties;
}

import { defineComponent, type Definition } from "../../../../lib/define.ts";
import { SENTINEL } from "../../../../lib/sentinel.ts";
import { tabsTab as tabsTabRaw } from "../../../../generated/component-styles.ts";

/** The `tabs.tab` member record: a single tab button (InstUI `Tabs.Tab`). */
export const tabsTab: Definition = defineComponent({
  name: "tabs.tab",
  css: (p) => tabsTabRaw.replaceAll(SENTINEL, p),
});
/** Standalone `tabs.tab` stylesheet. */
export const tabsTabCss: Definition["css"] = tabsTab.css;

/**
 * @component tabs.tab
 * @memberOf tabs
 * @selector .tab
 * @a11y Use `role="tab"` inside a `role="tablist"`, mirror `-selected` with `aria-selected`, point `aria-controls` at the panel, and mark a disabled tab with `aria-disabled` or the native `disabled`.
 * @summary A single tab button (InstUI `Tabs.Tab`, configured via the parent `Tabs`'s tab list); `-selected` marks the active one.
 * @modifier -selected — The active tab; same styling as `[aria-selected="true"]`.
 * @modifier -disabled — Non-interactive; same styling as `[aria-disabled="true"]`/`:disabled`.
 * @cssstate selected
 * @cssstate disabled
 * @remarks The parent `tabs`'s `-variant-secondary` modifier restyles this member into a rounded "folder" tab — see `tabs`'s own doc for that modifier.
 * @structure
 * @component tabs {
 *   .list {
 *     .tab {}
 *   }
 * }
 * @example -automatica11y
 * ```html
 * <div class="pfx-tabs" data-a11y-root>
 *   <div class="list" role="tablist" aria-label="Account settings">
 *     <button class="tab -selected" id="profile-tab" role="tab" aria-selected="true" aria-controls="profile-panel" tabindex="0" data-a11y-trigger>Profile</button>
 *     <button class="tab" id="security-tab" role="tab" aria-selected="false" aria-controls="security-panel" tabindex="-1">Security</button>
 *     <button class="tab -disabled" id="billing-tab" role="tab" aria-selected="false" aria-controls="billing-panel" tabindex="-1" disabled>Billing</button>
 *   </div>
 *   <div class="panel" id="profile-panel" role="tabpanel" aria-labelledby="profile-tab"></div>
 *   <div class="panel" id="security-panel" role="tabpanel" aria-labelledby="security-tab" hidden></div>
 *   <div class="panel" id="billing-panel" role="tabpanel" aria-labelledby="billing-tab" hidden></div>
 * </div>
 * <div class="pfx-tabs -variant-secondary">
 *   <div class="list" role="tablist" aria-label="Secondary settings">
 *     <button class="tab -selected" id="secondary-profile-tab" role="tab" aria-selected="true" aria-controls="secondary-profile-panel" tabindex="0">Profile</button>
 *     <button class="tab" id="secondary-security-tab" role="tab" aria-selected="false" aria-controls="secondary-security-panel" tabindex="-1">Security</button>
 *     <button class="tab -disabled" id="secondary-billing-tab" role="tab" aria-selected="false" aria-controls="secondary-billing-panel" tabindex="-1" disabled>Billing</button>
 *   </div>
 *   <div class="panel" id="secondary-profile-panel" role="tabpanel" aria-labelledby="secondary-profile-tab"></div>
 *   <div class="panel" id="secondary-security-panel" role="tabpanel" aria-labelledby="secondary-security-tab" hidden></div>
 *   <div class="panel" id="secondary-billing-panel" role="tabpanel" aria-labelledby="secondary-billing-tab" hidden></div>
 * </div>
 * ```
 */
@scope (.pfx-tabs) {
  .tab {
    appearance: none;
    -webkit-appearance: none;
    background: transparent;
    border: 0;
    color: var(--instui-component-tabs-tab-default-text-color);
    font-family: var(--instui-component-tabs-tab-font-family);
    font-size: var(--instui-component-tabs-tab-font-size);
    font-weight: var(--instui-component-tabs-tab-font-weight);
    line-height: 1;
    padding: 1rem 1.25rem;
    cursor: pointer;
    user-select: none;
    white-space: nowrap;
    position: relative;
    z-index: 1;
    /* Layout-stable underline: always 0.25rem, coloured only when hovered or selected. */
    border-bottom: 0.25rem solid transparent;
    margin-bottom: calc(-1 * var(--instui-component-tabs-panel-border-width));
  }

  .tab:hover:not(.-selected):not(.-disabled):not([aria-selected="true"]):not(
      [aria-disabled="true"]
    ) {
    border-bottom-color: var(--instui-component-tabs-tab-default-hover-border-color);
  }

  .tab.-selected,
  .tab[aria-selected="true"] {
    border-bottom-color: var(--instui-component-tabs-tab-default-selected-border-color);
  }

  .tab.-disabled,
  .tab[aria-disabled="true"],
  .tab:disabled {
    opacity: 0.5;
    font-weight: normal;
    cursor: default;

    @media (prefers-reduced-transparency: reduce) {
      opacity: 1;
      color: var(--instui-color-text-muted);
    }
  }

  /* Secondary variant (the parent tabs's `-variant-secondary`): rounded "folder" tabs; the selected
   tab's bottom border matches the panel background so it visually connects into the panel below. */
  :scope {
    &.-variant-secondary .tab {
      padding: 0.75rem 1rem;
      line-height: var(--instui-component-tabs-tab-line-height);
      color: var(--instui-component-tabs-tab-secondary-text-color);
      margin-inline-end: 0.2em;
      margin-bottom: calc(-1 * var(--instui-component-tabs-panel-border-width));
      border: var(--instui-component-tabs-panel-border-width) solid transparent;
      border-radius: 0.1875rem 0.1875rem 0 0;
    }

    &.-variant-secondary .tab:first-of-type {
      margin-inline-start: 0;
    }

    &.-variant-secondary
      .tab:hover:not(.-selected):not(.-disabled):not([aria-selected="true"]):not(
        [aria-disabled="true"]
      ) {
      background: var(--instui-component-tabs-tab-secondary-selected-background);
      border-color: var(--instui-component-tabs-tab-secondary-selected-border-color);
      color: var(--instui-component-tabs-tab-secondary-selected-text-color);
    }

    &.-variant-secondary .tab.-selected,
    &.-variant-secondary .tab[aria-selected="true"] {
      background: var(--instui-component-tabs-tab-secondary-selected-background);
      border-color: var(--instui-component-tabs-tab-secondary-selected-border-color);
      border-bottom-color: var(--instui-component-tabs-tab-secondary-selected-background);
      color: var(--instui-component-tabs-tab-secondary-selected-text-color);
    }
  }
}

