import { SENTINEL } from "../../../../lib/sentinel.ts";
import { tableCell as tableCellRaw } from "../../../../generated/component-styles.ts";

/** The `table.cell` member record: a data cell (InstUI `Table.Cell`). */
export const tableCell: Definition = defineComponent({
  name: "table.cell",
  css: (p) => tableCellRaw.replaceAll(SENTINEL, p),
});
/** Standalone `table.cell` stylesheet. */
export const tableCellCss: Definition["css"] = tableCell.css;

/**
 * @component table.cell
 * @memberOf table
 * @selector td
 * @a11y Use a native `<td>`. In `-layout-stacked` the column label is generated content that assistive technology may not announce reliably, so keep the column relationship available, for example with `headers`.
 * @summary A data cell (InstUI `Table.Cell`).
 * @remarks The parent `table`'s `-layout-stacked` modifier stacks this member as a block and labels it via `::before` — see `table`'s own doc for that modifier.
 * @structure
 * @component table {
 *   tbody {
 *     tr {
 *       td {}
 *     }
 *   }
 * }
 * @example -automatica11y
 * ```html
 * <table class="pfx-table -hover">
 *   <caption id="table-cell-caption">Top-rated films</caption>
 *   <thead>
 *     <tr>
 *       <th scope="col">Rank</th>
 *       <th scope="col">Title</th>
 *       <th scope="col">Year</th>
 *       <th scope="col">Rating</th>
 *     </tr>
 *   </thead>
 *   <tbody>
 *     <tr>
 *       <th scope="row">1</th>
 *       <td>The Shawshank Redemption</td>
 *       <td>1994</td>
 *       <td>9.3</td>
 *     </tr>
 *     <tr>
 *       <th scope="row">2</th>
 *       <td>The Godfather</td>
 *       <td>1972</td>
 *       <td>9.2</td>
 *     </tr>
 *     <tr>
 *       <th scope="row">3</th>
 *       <td>The Godfather: Part II</td>
 *       <td>1974</td>
 *       <td>9.0</td>
 *     </tr>
 *   </tbody>
 * </table>
 * <table class="pfx-table -layout-stacked"><caption>Stacked cells</caption><thead><tr><th scope="col">Title</th><th scope="col">Rating</th></tr></thead><tbody><tr><th scope="row" data-label="Title">The Godfather</th><td data-label="Rating">9.2</td></tr></tbody></table>
 * <div class="pfx-container"><table class="pfx-table -layout-responsive"><caption>Responsive cells</caption><thead><tr><th scope="col">Title</th><th scope="col">Rating</th></tr></thead><tbody><tr><th scope="row" data-label="Title">The Godfather</th><td data-label="Rating">9.2</td></tr></tbody></table></div>
 * ```
 */
.pfx-table td {
  color: var(--instui-component-table-cell-color);
  line-height: var(--instui-component-table-cell-line-height);
  padding: var(--instui-component-table-cell-padding-vertical)
    var(--instui-component-table-cell-padding-horizontal);
}

/* No border of its own — the separator lives on the row (see table.row). Reset with tbody specificity
 (0,1,2) so a host stylesheet's cell borders (e.g. `.pantoken-prose td`, 0,1,1) can't leak in. */
.pfx-table tbody td {
  border: 0;
}

/* layout="stacked": stack as a block, labelled by its column via ::before (pure CSS can't pull the
 <th> text automatically, so the author supplies a `data-label` per cell). */
.pfx-table.-layout-stacked td {
  display: block;
  width: auto;
}

.pfx-table.-layout-stacked tbody td[data-label]::before {
  content: attr(data-label);
  display: block;
  font-weight: var(--instui-component-table-head-font-weight);
  color: var(--instui-component-table-col-header-color);
}

import { modalCss } from "@pantoken/components";
import { initModal } from "@pantoken/interactions";
import type { ElementDefinition } from "../lib/context.ts";

/**
 * `<instui-modal>` — a real `<dialog>`, so it gets focus trapping, Escape-to-close, and a
 * `::backdrop` for free. The `open` attribute drives `showModal()`/`close()`; a native dismissal
 * (such as Escape) reflects back to the attribute and re-fires as a bubbling `close`
 * event. Drivable from light DOM via Invoker Commands — a
 * `<button command="--show|--close|--toggle" commandfor="modal-id">` toggles it by id. Content goes
 * in the default slot.
 *
 * @example
 * ```html
 * <button command="--show" commandfor="confirm">Delete…</button>
 * <instui-modal id="confirm">
 *   <h2>Delete this item?</h2>
 *   <button command="--close" commandfor="confirm">Cancel</button>
 * </instui-modal>
 * ```
 */
export const modal: ElementDefinition = {
  name: "modal",
  define: (ctx) => {
    if (ctx.registry.get("instui-modal")) return;
    ctx.registry.define(
      "instui-modal",
      class extends HTMLElement {
        static observedAttributes = ["open"];
        constructor() {
          super();
          this.attachShadow({ mode: "open" });
        }
        connectedCallback(): void {
          const root = this.shadowRoot;
          if (root && !root.querySelector("dialog")) {
            root.innerHTML = `<style>:host{display:contents}${modalCss(ctx.I)}</style><dialog class="instui-modal" part="modal"><slot></slot></dialog>`;
            const dialog = root.querySelector<HTMLDialogElement>("dialog");
            if (dialog) initModal(this, dialog, ctx.onCommand);
          }
        }
