  type: "array",
  minItems: 1,
  maxItems: 32,
  items: {
    type: "object",
    properties: {
      id: drilldownPageId,
      items: {
        type: "array",
        minItems: 1,
        maxItems: 64,
        items: {
          type: "object",
          properties: {
            back: dynamicBoolean,
            label: dynamicString,
            target: drilldownPageId,
