 * @returns The merged vite-plus config.
 */
export function extendBase(overrides: ViteUserConfig): ViteUserConfig {
  return mergeConfig(
    baseConfig as unknown as Record<string, unknown>,
    overrides as unknown as Record<string, unknown>,
  ) as ViteUserConfig;
}

